-- This is intentionally conditional: pages changed by an administrator are preserved.
-- No schema change; no content update occurs unless title, body and SEO still match the original seed.
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='gioi-thieu' AND title='Về Xanh Sky First' AND status='published' AND blocks_json='[{"type":"heading","text":"Không gian để sự quan tâm trở thành hành động"},{"type":"paragraph","text":"Xanh Sky First được phát triển như một không gian dành cho môi trường, cộng đồng và phát triển bền vững trong hệ sinh thái Sky First. Xanh không giới hạn mình ở một chiến dịch hoặc một hình thức tình nguyện duy nhất, mà xây dựng hành trình từ nhận thức đến hành động: tìm hiểu vấn đề, tiếp cận kiến thức, tham gia phù hợp, đóng góp chuyên môn và cùng phát triển giải pháp có căn cứ."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Bản sắc của Xanh nằm ở cách tiếp cận có chiều sâu. Trước một vấn đề, chúng tôi khuyến khích người tham gia tìm hiểu nguyên nhân, bối cảnh và những bên liên quan thay vì chỉ nhìn vào hình ảnh dễ gây chú ý. Một bài viết có nguồn đáng tin, một buổi chia sẻ có mục tiêu rõ ràng, một ý tưởng được kiểm tra trước khi thực hiện hay một thói quen bền vững đều có thể là điểm khởi đầu có ích."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Xanh hướng đến việc tạo điều kiện để người trẻ, cộng đồng địa phương, người có chuyên môn và đơn vị đồng hành có thể gặp nhau quanh những mục tiêu phù hợp. Mỗi người có thể tham gia ở mức độ khác nhau: học hỏi, chia sẻ tài nguyên, góp ý phương án, hỗ trợ truyền thông, phát triển công cụ hoặc tham gia hoạt động trực tiếp khi có chương trình được công bố. Không có một cách đóng góp duy nhất dành cho tất cả mọi người."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Trong quá trình phát triển, Xanh ưu tiên thông tin rõ ràng, mục tiêu có thể kiểm tra, phạm vi trách nhiệm phù hợp và việc ghi nhận trung thực. Chúng tôi không sử dụng số liệu chưa xác minh để tạo cảm giác thành tích, cũng không xem một chương trình hoàn tất chỉ vì sự kiện đã kết thúc. Kinh nghiệm, tài liệu, phản hồi và kết quả thực tế cần được lưu lại để các bước tiếp theo có thể học hỏi từ những gì đã diễn ra."}]' AND seo_json='{"title":"Về Xanh Sky First | Xanh Sky First","description":"Không gian để sự quan tâm trở thành hành động. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Xanh Sky First là khu vực thông tin và kết nối về môi trường, cộng đồng và phát triển bền vững trong hệ sinh thái Sky First. Website tập hợp các nội dung đã công bố để người đọc tìm hiểu trước khi quyết định tham gia."},{"type":"heading","text":"Bạn có thể tìm thấy gì ở đây?"},{"type":"paragraph","text":"Các mục Dự án, Hoạt động, Cơ hội và Sáng kiến giúp bạn theo dõi từng chương trình theo thông tin hiện có. Thư viện Xanh cung cấp tài nguyên để tìm hiểu sâu hơn; Tin tức cập nhật những nội dung đã được biên tập và xuất bản. Mỗi mục có phạm vi riêng, vì vậy hãy đọc phần mô tả và điều kiện trước khi gửi hồ sơ."},{"type":"heading","text":"Thông tin cần rõ ràng"},{"type":"paragraph","text":"Một kế hoạch không đồng nghĩa với hoạt động đã hoàn thành; lượt tham gia cũng không nhất thiết là số người riêng biệt. Khi một nội dung có số liệu, trạng thái hoặc mốc thời gian, các thông tin đó cần được đọc theo phần giải thích đi kèm. Nếu chưa có thông tin xác nhận, website không nên trình bày giả định như kết quả."},{"type":"heading","text":"Bắt đầu theo nhu cầu của bạn"},{"type":"paragraph","text":"Bạn có thể bắt đầu bằng việc đọc một tài nguyên, xem lịch hoạt động, tìm cơ hội phù hợp hoặc gửi câu hỏi qua trang Liên hệ. Không cần đăng ký trước khi hiểu rõ nhiệm vụ, thời gian và thông tin được yêu cầu."}]',seo_json='{"title":"Giới thiệu Xanh Sky First | Thông tin và cách tham gia","description":"Tìm hiểu phạm vi nội dung của Xanh Sky First, các chủ đề môi trường và cộng đồng, cùng cách theo dõi hoạt động đã công bố."}',updated_at=datetime('now') WHERE slug='gioi-thieu' AND title='Về Xanh Sky First' AND status='published' AND blocks_json='[{"type":"heading","text":"Không gian để sự quan tâm trở thành hành động"},{"type":"paragraph","text":"Xanh Sky First được phát triển như một không gian dành cho môi trường, cộng đồng và phát triển bền vững trong hệ sinh thái Sky First. Xanh không giới hạn mình ở một chiến dịch hoặc một hình thức tình nguyện duy nhất, mà xây dựng hành trình từ nhận thức đến hành động: tìm hiểu vấn đề, tiếp cận kiến thức, tham gia phù hợp, đóng góp chuyên môn và cùng phát triển giải pháp có căn cứ."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Bản sắc của Xanh nằm ở cách tiếp cận có chiều sâu. Trước một vấn đề, chúng tôi khuyến khích người tham gia tìm hiểu nguyên nhân, bối cảnh và những bên liên quan thay vì chỉ nhìn vào hình ảnh dễ gây chú ý. Một bài viết có nguồn đáng tin, một buổi chia sẻ có mục tiêu rõ ràng, một ý tưởng được kiểm tra trước khi thực hiện hay một thói quen bền vững đều có thể là điểm khởi đầu có ích."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Xanh hướng đến việc tạo điều kiện để người trẻ, cộng đồng địa phương, người có chuyên môn và đơn vị đồng hành có thể gặp nhau quanh những mục tiêu phù hợp. Mỗi người có thể tham gia ở mức độ khác nhau: học hỏi, chia sẻ tài nguyên, góp ý phương án, hỗ trợ truyền thông, phát triển công cụ hoặc tham gia hoạt động trực tiếp khi có chương trình được công bố. Không có một cách đóng góp duy nhất dành cho tất cả mọi người."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Trong quá trình phát triển, Xanh ưu tiên thông tin rõ ràng, mục tiêu có thể kiểm tra, phạm vi trách nhiệm phù hợp và việc ghi nhận trung thực. Chúng tôi không sử dụng số liệu chưa xác minh để tạo cảm giác thành tích, cũng không xem một chương trình hoàn tất chỉ vì sự kiện đã kết thúc. Kinh nghiệm, tài liệu, phản hồi và kết quả thực tế cần được lưu lại để các bước tiếp theo có thể học hỏi từ những gì đã diễn ra."}]' AND seo_json='{"title":"Về Xanh Sky First | Xanh Sky First","description":"Không gian để sự quan tâm trở thành hành động. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='co-hoi-chuyen-mon' AND title='Đóng góp chuyên môn' AND status='published' AND blocks_json='[{"type":"heading","text":"Chuyên môn có thể giúp một sáng kiến trở nên rõ ràng, khả thi và có cơ sở hơn."},{"type":"paragraph","text":"Xanh có thể tiếp nhận đóng góp từ nhiều lĩnh vực phù hợp như giáo dục, thiết kế, công nghệ, truyền thông, dữ liệu, tổ chức hoạt động, nghiên cứu, quản lý dự án và phát triển cộng đồng. Mỗi lời mời cần nêu vấn đề cần giải quyết, đầu ra mong đợi, thời gian dự kiến và mức độ phối hợp. Cách mô tả cụ thể giúp người quan tâm đánh giá xem năng lực của họ có phù hợp hay không."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Khi chuyên gia hoặc người đóng góp chia sẻ tài liệu, công cụ hay ý kiến, hai bên nên thống nhất phạm vi sử dụng, quyền sở hữu, ghi nhận đóng góp và điều kiện bảo mật nếu có. Không nên coi một cuộc trao đổi ban đầu là cam kết hợp tác dài hạn. Thỏa thuận cần phù hợp với quy mô công việc và không tạo ra kỳ vọng không có cơ sở."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Đóng góp chuyên môn không chỉ là đưa ra câu trả lời mà còn giúp đặt câu hỏi đúng, nhận diện rủi ro và chỉ ra giới hạn của phương án. Xanh khuyến khích cách làm có giải thích và tài liệu hóa để người khác có thể học hỏi. Mọi kết quả công bố cần được rà soát về tính chính xác và không được gán danh nghĩa chuyên gia khi chưa có sự đồng ý."}]' AND seo_json='{"title":"Đóng góp chuyên môn | Xanh Sky First","description":"Chuyên môn có thể giúp một sáng kiến trở nên rõ ràng, khả thi và có cơ sở hơn. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Đóng góp chuyên môn hiệu quả nhất khi vấn đề cần giải quyết được mô tả rõ. Giáo dục, thiết kế, công nghệ, truyền thông, dữ liệu, nghiên cứu hay tổ chức hoạt động đều có thể hữu ích tùy theo nhu cầu thực tế của từng chương trình."},{"type":"heading","text":"Trước khi nhận một phần việc"},{"type":"paragraph","text":"Hãy thống nhất mục tiêu, sản phẩm cần bàn giao, thời gian dự kiến, đầu mối phối hợp và những giới hạn hiện có. Nếu yêu cầu chưa rõ, nên trao đổi để làm rõ trước khi bắt đầu thay vì tự suy đoán hoặc hứa một kết quả chưa có đủ nguồn lực."},{"type":"heading","text":"Thỏa thuận ngay từ đầu"},{"type":"paragraph","text":"Khi chia sẻ tài liệu, công cụ hoặc ý tưởng, các bên cần hiểu phạm vi sử dụng, cách ghi nhận tác giả, quyền sở hữu và yêu cầu bảo mật nếu có. Một buổi trao đổi ban đầu chưa phải cam kết hợp tác dài hạn; mọi thỏa thuận nên phù hợp với quy mô công việc."},{"type":"heading","text":"Chia sẻ cả căn cứ lẫn giới hạn"},{"type":"paragraph","text":"Một đóng góp tốt không chỉ đưa ra phương án mà còn chỉ rõ giả định, rủi ro và điều kiện để phương án có thể áp dụng. Không công bố tên hoặc danh nghĩa chuyên gia khi chưa có sự đồng ý của người liên quan."}]',seo_json='{"title":"Đóng góp chuyên môn | Xanh Sky First","description":"Tìm hiểu cách đề xuất hỗ trợ chuyên môn và những điểm cần thống nhất về phạm vi, đầu ra, thời gian, quyền sử dụng và ghi nhận đóng góp."}',updated_at=datetime('now') WHERE slug='co-hoi-chuyen-mon' AND title='Đóng góp chuyên môn' AND status='published' AND blocks_json='[{"type":"heading","text":"Chuyên môn có thể giúp một sáng kiến trở nên rõ ràng, khả thi và có cơ sở hơn."},{"type":"paragraph","text":"Xanh có thể tiếp nhận đóng góp từ nhiều lĩnh vực phù hợp như giáo dục, thiết kế, công nghệ, truyền thông, dữ liệu, tổ chức hoạt động, nghiên cứu, quản lý dự án và phát triển cộng đồng. Mỗi lời mời cần nêu vấn đề cần giải quyết, đầu ra mong đợi, thời gian dự kiến và mức độ phối hợp. Cách mô tả cụ thể giúp người quan tâm đánh giá xem năng lực của họ có phù hợp hay không."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Khi chuyên gia hoặc người đóng góp chia sẻ tài liệu, công cụ hay ý kiến, hai bên nên thống nhất phạm vi sử dụng, quyền sở hữu, ghi nhận đóng góp và điều kiện bảo mật nếu có. Không nên coi một cuộc trao đổi ban đầu là cam kết hợp tác dài hạn. Thỏa thuận cần phù hợp với quy mô công việc và không tạo ra kỳ vọng không có cơ sở."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Đóng góp chuyên môn không chỉ là đưa ra câu trả lời mà còn giúp đặt câu hỏi đúng, nhận diện rủi ro và chỉ ra giới hạn của phương án. Xanh khuyến khích cách làm có giải thích và tài liệu hóa để người khác có thể học hỏi. Mọi kết quả công bố cần được rà soát về tính chính xác và không được gán danh nghĩa chuyên gia khi chưa có sự đồng ý."}]' AND seo_json='{"title":"Đóng góp chuyên môn | Xanh Sky First","description":"Chuyên môn có thể giúp một sáng kiến trở nên rõ ràng, khả thi và có cơ sở hơn. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='co-hoi-tinh-nguyen' AND title='Cơ hội tình nguyện' AND status='published' AND blocks_json='[{"type":"heading","text":"Tình nguyện là một cách đóng góp, nhưng nhiệm vụ cần phù hợp với năng lực, thời gian và điều kiện của mỗi người."},{"type":"paragraph","text":"Mô tả cơ hội tình nguyện cần làm rõ mục tiêu, phần việc, địa điểm, thời lượng dự kiến, yêu cầu tối thiểu và đầu mối hỗ trợ. Nếu nhiệm vụ cần có mặt trực tiếp, điều đó phải được nêu rõ trước khi người dùng gửi hồ sơ. Nếu có thể làm trực tuyến, trang nên mô tả cách giao việc, cách trao đổi và cách bàn giao kết quả."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Người quan tâm không nhất thiết phải có kinh nghiệm chuyên môn từ đầu, nhưng cần hiểu cam kết cụ thể của nhiệm vụ. Các yêu cầu về tuổi, người giám hộ, an toàn hoặc kỹ năng cần tương xứng với bối cảnh thực tế và được thông báo trước. Không yêu cầu ứng viên cung cấp tài liệu không cần thiết; không hứa hẹn giấy chứng nhận, hỗ trợ hoặc quyền lợi chưa được phê duyệt."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Sau khi gửi hồ sơ, người đăng ký nên nhận xác nhận tiếp nhận nếu hệ thống đã lưu thành công. Việc xét chọn cần dựa trên nhu cầu thật và tiêu chí đã công bố. Nếu không được nhận ở thời điểm hiện tại, người đăng ký có thể theo dõi cơ hội khác hoặc đóng góp theo hình thức phù hợp hơn."}]' AND seo_json='{"title":"Cơ hội tình nguyện | Xanh Sky First","description":"Tình nguyện là một cách đóng góp, nhưng nhiệm vụ cần phù hợp với năng lực, thời gian và điều kiện của mỗi người. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Một cơ hội tình nguyện cần cho người đăng ký biết mình sẽ làm gì và cam kết trong bao lâu. Tên chương trình thôi chưa đủ; phần mô tả nên chỉ ra mục tiêu, nhiệm vụ cụ thể, địa điểm, thời lượng và người liên hệ."},{"type":"heading","text":"Đọc kỹ yêu cầu của nhiệm vụ"},{"type":"paragraph","text":"Nếu cần có mặt trực tiếp, yêu cầu đó phải được nêu trước khi đăng ký. Nếu làm trực tuyến, hãy tìm hiểu cách nhận việc, trao đổi và bàn giao kết quả. Điều kiện về tuổi, kỹ năng, an toàn hoặc người giám hộ cần phù hợp với bối cảnh và được công bố rõ."},{"type":"heading","text":"Quyền lợi phải được xác nhận"},{"type":"paragraph","text":"Không nên mặc định mọi hoạt động đều có hỗ trợ chi phí, chứng nhận hoặc quyền lợi giống nhau. Chỉ coi một quyền lợi là chắc chắn khi thông tin của chính chương trình đã nêu rõ và được duyệt. Hồ sơ cũng không nên yêu cầu giấy tờ không cần thiết cho nhiệm vụ."},{"type":"heading","text":"Sau khi gửi hồ sơ"},{"type":"paragraph","text":"Hãy lưu mã tiếp nhận nếu hệ thống cấp mã và theo dõi trạng thái bằng đường dẫn tra cứu. Việc gửi đăng ký không đồng nghĩa được lựa chọn ngay; người phụ trách có thể cần thời gian xem xét hoặc hỏi thêm thông tin. Nếu nhiệm vụ chưa phù hợp, bạn vẫn có thể theo dõi cơ hội khác."}]',seo_json='{"title":"Cơ hội tình nguyện | Xanh Sky First","description":"Đọc mục tiêu, nhiệm vụ, thời gian, địa điểm và yêu cầu của từng cơ hội tình nguyện trước khi gửi đăng ký."}',updated_at=datetime('now') WHERE slug='co-hoi-tinh-nguyen' AND title='Cơ hội tình nguyện' AND status='published' AND blocks_json='[{"type":"heading","text":"Tình nguyện là một cách đóng góp, nhưng nhiệm vụ cần phù hợp với năng lực, thời gian và điều kiện của mỗi người."},{"type":"paragraph","text":"Mô tả cơ hội tình nguyện cần làm rõ mục tiêu, phần việc, địa điểm, thời lượng dự kiến, yêu cầu tối thiểu và đầu mối hỗ trợ. Nếu nhiệm vụ cần có mặt trực tiếp, điều đó phải được nêu rõ trước khi người dùng gửi hồ sơ. Nếu có thể làm trực tuyến, trang nên mô tả cách giao việc, cách trao đổi và cách bàn giao kết quả."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Người quan tâm không nhất thiết phải có kinh nghiệm chuyên môn từ đầu, nhưng cần hiểu cam kết cụ thể của nhiệm vụ. Các yêu cầu về tuổi, người giám hộ, an toàn hoặc kỹ năng cần tương xứng với bối cảnh thực tế và được thông báo trước. Không yêu cầu ứng viên cung cấp tài liệu không cần thiết; không hứa hẹn giấy chứng nhận, hỗ trợ hoặc quyền lợi chưa được phê duyệt."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Sau khi gửi hồ sơ, người đăng ký nên nhận xác nhận tiếp nhận nếu hệ thống đã lưu thành công. Việc xét chọn cần dựa trên nhu cầu thật và tiêu chí đã công bố. Nếu không được nhận ở thời điểm hiện tại, người đăng ký có thể theo dõi cơ hội khác hoặc đóng góp theo hình thức phù hợp hơn."}]' AND seo_json='{"title":"Cơ hội tình nguyện | Xanh Sky First","description":"Tình nguyện là một cách đóng góp, nhưng nhiệm vụ cần phù hợp với năng lực, thời gian và điều kiện của mỗi người. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='con-nguoi-quyen-rieng-tu' AND title='Thông tin và quyền riêng tư' AND status='published' AND blocks_json='[{"type":"heading","text":"Việc giới thiệu con người cần dựa trên sự đồng ý, tính chính xác và mục đích công khai rõ ràng."},{"type":"paragraph","text":"Hồ sơ công khai nên tập trung vào tên, vai trò, lĩnh vực đóng góp và thông tin giới thiệu mà người liên quan đã đồng ý chia sẻ. Không cần công khai địa chỉ riêng, thông tin liên hệ cá nhân, giấy tờ định danh hoặc dữ liệu không phục vụ mục đích giới thiệu. Ảnh chân dung cũng cần có quyền sử dụng phù hợp và văn bản thay thế hỗ trợ người dùng công nghệ hỗ trợ."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Quản trị viên cần phân biệt hồ sơ nội bộ với hồ sơ công khai. Việc có dữ liệu trong Management Center không tự động có nghĩa dữ liệu được phép hiển thị ngoài website hoặc cho công cụ tìm kiếm lập chỉ mục. Khi vai trò kết thúc hoặc người liên quan yêu cầu chỉnh sửa phù hợp, thông tin cần được rà soát theo quy trình và giữ nhật ký cần thiết."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Câu chuyện cá nhân phải được trình bày đúng ngữ cảnh và không khai thác hoàn cảnh riêng tư để tạo cảm xúc. Nếu sử dụng trích dẫn, hình ảnh hay nội dung do người khác cung cấp, cần làm rõ sự đồng ý và phạm vi sử dụng. Cách quản lý thận trọng giúp Xanh duy trì lòng tin và giảm rủi ro cho cộng đồng."}]' AND seo_json='{"title":"Thông tin và quyền riêng tư | Xanh Sky First","description":"Việc giới thiệu con người cần dựa trên sự đồng ý, tính chính xác và mục đích công khai rõ ràng. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Hồ sơ trên website chỉ nên giới thiệu thông tin cần thiết cho mục đích công khai: tên, vai trò, lĩnh vực đóng góp và phần giới thiệu đã được người liên quan đồng ý chia sẻ."},{"type":"heading","text":"Không phải dữ liệu nội bộ nào cũng được công khai"},{"type":"paragraph","text":"Địa chỉ riêng, giấy tờ định danh, thông tin liên hệ cá nhân và dữ liệu không liên quan đến mục đích giới thiệu không nên xuất hiện trên trang công khai. Ảnh chân dung cần có quyền sử dụng phù hợp; ảnh cần văn bản thay thế để người dùng công nghệ hỗ trợ hiểu được nội dung chính."},{"type":"heading","text":"Rà soát khi vai trò thay đổi"},{"type":"paragraph","text":"Quản trị viên cần phân biệt hồ sơ nội bộ với hồ sơ đã bật công khai và quyền lập chỉ mục. Việc một bản ghi tồn tại trong khu vực quản trị không tự động cho phép đưa nó lên website hoặc công cụ tìm kiếm. Khi vai trò kết thúc hoặc có yêu cầu chỉnh sửa phù hợp, thông tin cần được kiểm tra lại."},{"type":"heading","text":"Tôn trọng câu chuyện của mỗi người"},{"type":"paragraph","text":"Trích dẫn, hình ảnh và câu chuyện cá nhân cần được dùng đúng ngữ cảnh và đúng phạm vi đã thống nhất. Không khai thác hoàn cảnh riêng tư để tạo cảm xúc hoặc gán cho một người quan điểm mà họ không đưa ra."}]',seo_json='{"title":"Thông tin và quyền riêng tư của hồ sơ | Xanh Sky First","description":"Nguyên tắc công khai hồ sơ con người: đúng thông tin, có sự đồng ý và chỉ chia sẻ dữ liệu cần cho mục đích giới thiệu."}',updated_at=datetime('now') WHERE slug='con-nguoi-quyen-rieng-tu' AND title='Thông tin và quyền riêng tư' AND status='published' AND blocks_json='[{"type":"heading","text":"Việc giới thiệu con người cần dựa trên sự đồng ý, tính chính xác và mục đích công khai rõ ràng."},{"type":"paragraph","text":"Hồ sơ công khai nên tập trung vào tên, vai trò, lĩnh vực đóng góp và thông tin giới thiệu mà người liên quan đã đồng ý chia sẻ. Không cần công khai địa chỉ riêng, thông tin liên hệ cá nhân, giấy tờ định danh hoặc dữ liệu không phục vụ mục đích giới thiệu. Ảnh chân dung cũng cần có quyền sử dụng phù hợp và văn bản thay thế hỗ trợ người dùng công nghệ hỗ trợ."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Quản trị viên cần phân biệt hồ sơ nội bộ với hồ sơ công khai. Việc có dữ liệu trong Management Center không tự động có nghĩa dữ liệu được phép hiển thị ngoài website hoặc cho công cụ tìm kiếm lập chỉ mục. Khi vai trò kết thúc hoặc người liên quan yêu cầu chỉnh sửa phù hợp, thông tin cần được rà soát theo quy trình và giữ nhật ký cần thiết."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Câu chuyện cá nhân phải được trình bày đúng ngữ cảnh và không khai thác hoàn cảnh riêng tư để tạo cảm xúc. Nếu sử dụng trích dẫn, hình ảnh hay nội dung do người khác cung cấp, cần làm rõ sự đồng ý và phạm vi sử dụng. Cách quản lý thận trọng giúp Xanh duy trì lòng tin và giảm rủi ro cho cộng đồng."}]' AND seo_json='{"title":"Thông tin và quyền riêng tư | Xanh Sky First","description":"Việc giới thiệu con người cần dựa trên sự đồng ý, tính chính xác và mục đích công khai rõ ràng. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='con-nguoi-vai-tro' AND title='Vai trò và cách phối hợp' AND status='published' AND blocks_json='[{"type":"heading","text":"Vai trò rõ ràng giúp mỗi người biết phạm vi trách nhiệm, đầu ra và cách phối hợp với các thành viên khác."},{"type":"paragraph","text":"Một vai trò nên được mô tả bằng nhiệm vụ, phạm vi quyết định, người phối hợp và tiêu chí hoàn thành thay vì chỉ bằng tên chức danh. Đối với nhiệm vụ ngắn hạn, mô tả rõ đầu ra và hạn hoàn thành thường có ích hơn việc tạo thêm tầng nấc tổ chức. Khi vai trò thay đổi, người liên quan cần được thông báo và dữ liệu công khai phải được cập nhật."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Phối hợp hiệu quả đòi hỏi thông tin được chia sẻ đúng người, đúng thời điểm và qua kênh phù hợp. Các cuộc họp nên có mục tiêu, nội dung chuẩn bị và kết luận có thể theo dõi. Công việc cần được ghi nhận để tránh phụ thuộc vào trí nhớ của một cá nhân. Khi có bất đồng, nhóm nên làm rõ dữ kiện, trách nhiệm và tác động thay vì suy đoán động cơ hoặc công kích cá nhân."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Xanh hướng đến cách phối hợp tôn trọng khả năng và giới hạn của từng người. Thành viên nên được quyền nêu khó khăn, đề nghị hỗ trợ hoặc báo không thể tiếp tục một nhiệm vụ. Việc bàn giao rõ ràng, lưu tài liệu và phản hồi có xây dựng giúp công việc tiếp tục mà không tạo áp lực không cần thiết."}]' AND seo_json='{"title":"Vai trò và cách phối hợp | Xanh Sky First","description":"Vai trò rõ ràng giúp mỗi người biết phạm vi trách nhiệm, đầu ra và cách phối hợp với các thành viên khác. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Một mô tả vai trò rõ ràng trả lời ba câu hỏi: người phụ trách chịu trách nhiệm việc gì, phối hợp với ai và cần bàn giao kết quả nào. Tên chức danh chỉ là nhãn; nhiệm vụ và phạm vi quyết định mới giúp mọi người làm việc cùng nhau."},{"type":"heading","text":"Thống nhất trước khi bắt đầu"},{"type":"paragraph","text":"Với mỗi đầu việc, nên xác định người chịu trách nhiệm chính, thời hạn, kết quả cần có và kênh liên lạc. Những nhiệm vụ ngắn hạn không nhất thiết cần thêm tầng nấc tổ chức; mô tả cụ thể thường hữu ích hơn một danh xưng dài."},{"type":"heading","text":"Chia sẻ đúng thông tin"},{"type":"paragraph","text":"Thông tin cần đến đúng người vào đúng thời điểm. Cuộc họp nên có mục tiêu và kết luận có thể theo dõi; tài liệu cần được lưu ở nơi phù hợp để công việc không phụ thuộc vào trí nhớ của một cá nhân. Khi có bất đồng, hãy trao đổi bằng dữ kiện và tác động thay vì suy đoán động cơ."},{"type":"heading","text":"Bàn giao không tạo áp lực"},{"type":"paragraph","text":"Người thực hiện cần có thể nêu khó khăn, xin hỗ trợ hoặc báo rằng mình không thể tiếp tục một nhiệm vụ. Bàn giao sớm, rõ ràng và tôn trọng giới hạn giúp nhóm điều chỉnh công việc mà không gây áp lực không cần thiết."}]',seo_json='{"title":"Vai trò và cách phối hợp | Xanh Sky First","description":"Cách mô tả trách nhiệm, quyền quyết định, đầu ra và quy trình bàn giao để phối hợp công việc rõ ràng hơn."}',updated_at=datetime('now') WHERE slug='con-nguoi-vai-tro' AND title='Vai trò và cách phối hợp' AND status='published' AND blocks_json='[{"type":"heading","text":"Vai trò rõ ràng giúp mỗi người biết phạm vi trách nhiệm, đầu ra và cách phối hợp với các thành viên khác."},{"type":"paragraph","text":"Một vai trò nên được mô tả bằng nhiệm vụ, phạm vi quyết định, người phối hợp và tiêu chí hoàn thành thay vì chỉ bằng tên chức danh. Đối với nhiệm vụ ngắn hạn, mô tả rõ đầu ra và hạn hoàn thành thường có ích hơn việc tạo thêm tầng nấc tổ chức. Khi vai trò thay đổi, người liên quan cần được thông báo và dữ liệu công khai phải được cập nhật."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Phối hợp hiệu quả đòi hỏi thông tin được chia sẻ đúng người, đúng thời điểm và qua kênh phù hợp. Các cuộc họp nên có mục tiêu, nội dung chuẩn bị và kết luận có thể theo dõi. Công việc cần được ghi nhận để tránh phụ thuộc vào trí nhớ của một cá nhân. Khi có bất đồng, nhóm nên làm rõ dữ kiện, trách nhiệm và tác động thay vì suy đoán động cơ hoặc công kích cá nhân."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Xanh hướng đến cách phối hợp tôn trọng khả năng và giới hạn của từng người. Thành viên nên được quyền nêu khó khăn, đề nghị hỗ trợ hoặc báo không thể tiếp tục một nhiệm vụ. Việc bàn giao rõ ràng, lưu tài liệu và phản hồi có xây dựng giúp công việc tiếp tục mà không tạo áp lực không cần thiết."}]' AND seo_json='{"title":"Vai trò và cách phối hợp | Xanh Sky First","description":"Vai trò rõ ràng giúp mỗi người biết phạm vi trách nhiệm, đầu ra và cách phối hợp với các thành viên khác. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='du-an-dinh-huong' AND title='Định hướng phát triển dự án' AND status='published' AND blocks_json='[{"type":"heading","text":"Trang này trình bày cách một ý tưởng được chuyển thành đề xuất có thể đánh giá và triển khai."},{"type":"paragraph","text":"Một đề xuất cần mô tả vấn đề, bối cảnh địa phương, nhóm chịu ảnh hưởng và bằng chứng ban đầu. Nhóm xây dựng nên xác định điều gì đã biết, điều gì còn cần tìm hiểu và giả định nào có thể làm thay đổi giải pháp. Bước chuẩn bị này giúp tránh lựa chọn hoạt động chỉ vì dễ tổ chức hoặc dễ truyền thông mà chưa chắc phù hợp với nhu cầu thật."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Sau khi làm rõ vấn đề, cần xác định mục tiêu, phạm vi, sản phẩm đầu ra, người phụ trách, nguồn lực, lịch dự kiến và các rủi ro có thể gặp. Mục tiêu nên đủ cụ thể để đánh giá nhưng không buộc nhóm phải hứa hẹn kết quả ngoài khả năng kiểm soát. Với dự án môi trường, yếu tố an toàn, quản lý chất thải, quyền sử dụng hình ảnh và tác động ngoài dự kiến cần được cân nhắc ngay từ đầu."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Đề xuất được xem xét dựa trên mức độ phù hợp với định hướng Xanh, tính khả thi, lợi ích cộng đồng, tính minh bạch và khả năng học hỏi từ kết quả. Việc được tiếp nhận ý tưởng không đồng nghĩa dự án tự động được tài trợ hoặc triển khai. Trạng thái và các bước tiếp theo cần được phản hồi rõ ràng cho người đề xuất."}]' AND seo_json='{"title":"Định hướng phát triển dự án | Xanh Sky First","description":"Trang này trình bày cách một ý tưởng được chuyển thành đề xuất có thể đánh giá và triển khai. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Trước khi bắt đầu dự án, hãy mô tả vấn đề cần giải quyết bằng thông tin có thể kiểm tra. Bối cảnh địa phương, nhóm chịu ảnh hưởng và bằng chứng ban đầu giúp nhóm tránh chọn hoạt động chỉ vì dễ tổ chức hoặc dễ truyền thông."},{"type":"heading","text":"Làm rõ điều đã biết và điều còn thiếu"},{"type":"paragraph","text":"Ghi lại nguồn thông tin, giả định và câu hỏi chưa có câu trả lời. Nếu một giả định thay đổi có thể làm thay đổi giải pháp, hãy kiểm tra nó sớm. Người bị ảnh hưởng nên có cơ hội phản hồi khi điều kiện cho phép."},{"type":"heading","text":"Thiết kế phần việc có thể theo dõi"},{"type":"paragraph","text":"Một đề xuất cần nêu mục tiêu, phạm vi, sản phẩm đầu ra, người phụ trách, nguồn lực, lịch dự kiến và rủi ro. Mục tiêu nên đủ cụ thể để đánh giá nhưng không hứa hẹn kết quả vượt ngoài khả năng kiểm soát. Với dự án môi trường, hãy cân nhắc an toàn, quản lý chất thải, quyền sử dụng hình ảnh và tác động ngoài dự kiến."},{"type":"heading","text":"Đánh giá rồi điều chỉnh"},{"type":"paragraph","text":"Sau mỗi giai đoạn, so sánh kết quả với mục tiêu ban đầu, ghi nhận điều chưa đạt và lý do. Nếu cần thay đổi hướng đi, hãy cập nhật quyết định và mốc thời gian để người tham gia hiểu vì sao kế hoạch khác đi."}]',seo_json='{"title":"Định hướng phát triển dự án | Xanh Sky First","description":"Từ vấn đề thực tế đến đề xuất có thể đánh giá: xác định nhu cầu, mục tiêu, đầu ra, nguồn lực, rủi ro và cách theo dõi."}',updated_at=datetime('now') WHERE slug='du-an-dinh-huong' AND title='Định hướng phát triển dự án' AND status='published' AND blocks_json='[{"type":"heading","text":"Trang này trình bày cách một ý tưởng được chuyển thành đề xuất có thể đánh giá và triển khai."},{"type":"paragraph","text":"Một đề xuất cần mô tả vấn đề, bối cảnh địa phương, nhóm chịu ảnh hưởng và bằng chứng ban đầu. Nhóm xây dựng nên xác định điều gì đã biết, điều gì còn cần tìm hiểu và giả định nào có thể làm thay đổi giải pháp. Bước chuẩn bị này giúp tránh lựa chọn hoạt động chỉ vì dễ tổ chức hoặc dễ truyền thông mà chưa chắc phù hợp với nhu cầu thật."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Sau khi làm rõ vấn đề, cần xác định mục tiêu, phạm vi, sản phẩm đầu ra, người phụ trách, nguồn lực, lịch dự kiến và các rủi ro có thể gặp. Mục tiêu nên đủ cụ thể để đánh giá nhưng không buộc nhóm phải hứa hẹn kết quả ngoài khả năng kiểm soát. Với dự án môi trường, yếu tố an toàn, quản lý chất thải, quyền sử dụng hình ảnh và tác động ngoài dự kiến cần được cân nhắc ngay từ đầu."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Đề xuất được xem xét dựa trên mức độ phù hợp với định hướng Xanh, tính khả thi, lợi ích cộng đồng, tính minh bạch và khả năng học hỏi từ kết quả. Việc được tiếp nhận ý tưởng không đồng nghĩa dự án tự động được tài trợ hoặc triển khai. Trạng thái và các bước tiếp theo cần được phản hồi rõ ràng cho người đề xuất."}]' AND seo_json='{"title":"Định hướng phát triển dự án | Xanh Sky First","description":"Trang này trình bày cách một ý tưởng được chuyển thành đề xuất có thể đánh giá và triển khai. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='du-an-sang-kien' AND title='Sáng kiến xanh' AND status='published' AND blocks_json='[{"type":"heading","text":"Sáng kiến là cơ hội để biến câu hỏi thực tế thành phương án có thể thử nghiệm và cải thiện."},{"type":"paragraph","text":"Một sáng kiến có thể bắt đầu từ vấn đề nhỏ trong khu dân cư, trường học, không gian công cộng hoặc thói quen tiêu dùng. Người đề xuất nên mô tả vấn đề quan sát được, ai gặp khó khăn, giải pháp hiện có và điểm cần cải thiện. Cách diễn đạt rõ ràng giúp nhóm khác hiểu ý tưởng mà không phải dựa vào những lời mô tả chung chung như “xây dựng môi trường xanh hơn”."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Ý tưởng cần được đánh giá về khả năng thực hiện, chi phí, nguồn lực, độ an toàn, tác động tới các nhóm khác nhau và cách xác định hiệu quả. Với giải pháp mới, thử nghiệm ở phạm vi nhỏ thường giúp tìm ra hạn chế trước khi mở rộng. Nếu chưa có dữ liệu chứng minh hiệu quả, cần nói đó là giả thuyết hoặc kỳ vọng thay vì tuyên bố giải pháp đã tạo ra tác động."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Xanh khuyến khích việc ghi lại quá trình thử nghiệm, phản hồi của người sử dụng, các điều chỉnh và bài học rút ra. Một phương án chưa đạt mục tiêu vẫn có thể tạo ra tri thức có giá trị nếu kết quả được ghi nhận trung thực. Những sáng kiến phù hợp có thể được phát triển thêm khi có người phụ trách, điều kiện và nguồn lực rõ ràng."}]' AND seo_json='{"title":"Sáng kiến xanh | Xanh Sky First","description":"Sáng kiến là cơ hội để biến câu hỏi thực tế thành phương án có thể thử nghiệm và cải thiện. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Một sáng kiến có giá trị khi bắt đầu từ vấn đề cụ thể, không chỉ từ một ý tưởng nghe hấp dẫn. Hãy mô tả ai đang gặp khó khăn, tình huống diễn ra ở đâu và điều gì cho thấy cần tìm một cách làm khác."},{"type":"heading","text":"Giải pháp phải phù hợp với bối cảnh"},{"type":"paragraph","text":"Nêu cách giải pháp hoạt động, ai sẽ sử dụng, điều kiện để triển khai và phần nào vẫn cần thử nghiệm. Một mô hình có ích ở nơi này chưa chắc phù hợp nguyên trạng với nơi khác; chi phí, kỹ năng, hạ tầng và thói quen địa phương đều ảnh hưởng đến kết quả."},{"type":"heading","text":"Thử nhỏ trước khi mở rộng"},{"type":"paragraph","text":"Nếu có thể, hãy thử với phạm vi vừa đủ để phát hiện vấn đề. Xác định dấu hiệu nào cho thấy phương án hữu ích, dữ liệu nào cần ghi nhận và điều kiện nào buộc phải dừng hoặc điều chỉnh. Không lấy số người biết đến sáng kiến làm bằng chứng duy nhất cho hiệu quả."},{"type":"heading","text":"Mô tả trung thực tiến độ"},{"type":"paragraph","text":"Phân biệt rõ ý tưởng, bản thử nghiệm, hoạt động đang triển khai và giải pháp đã được đánh giá. Công bố kết quả cùng giới hạn của dữ liệu và ghi nhận đóng góp đúng với sự đồng ý của người liên quan."}]',seo_json='{"title":"Sáng kiến xanh | Xanh Sky First","description":"Cách trình bày sáng kiến từ vấn đề cần giải quyết đến giải pháp, đối tượng sử dụng, chi phí, rủi ro và cách thử nghiệm."}',updated_at=datetime('now') WHERE slug='du-an-sang-kien' AND title='Sáng kiến xanh' AND status='published' AND blocks_json='[{"type":"heading","text":"Sáng kiến là cơ hội để biến câu hỏi thực tế thành phương án có thể thử nghiệm và cải thiện."},{"type":"paragraph","text":"Một sáng kiến có thể bắt đầu từ vấn đề nhỏ trong khu dân cư, trường học, không gian công cộng hoặc thói quen tiêu dùng. Người đề xuất nên mô tả vấn đề quan sát được, ai gặp khó khăn, giải pháp hiện có và điểm cần cải thiện. Cách diễn đạt rõ ràng giúp nhóm khác hiểu ý tưởng mà không phải dựa vào những lời mô tả chung chung như “xây dựng môi trường xanh hơn”."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Ý tưởng cần được đánh giá về khả năng thực hiện, chi phí, nguồn lực, độ an toàn, tác động tới các nhóm khác nhau và cách xác định hiệu quả. Với giải pháp mới, thử nghiệm ở phạm vi nhỏ thường giúp tìm ra hạn chế trước khi mở rộng. Nếu chưa có dữ liệu chứng minh hiệu quả, cần nói đó là giả thuyết hoặc kỳ vọng thay vì tuyên bố giải pháp đã tạo ra tác động."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Xanh khuyến khích việc ghi lại quá trình thử nghiệm, phản hồi của người sử dụng, các điều chỉnh và bài học rút ra. Một phương án chưa đạt mục tiêu vẫn có thể tạo ra tri thức có giá trị nếu kết quả được ghi nhận trung thực. Những sáng kiến phù hợp có thể được phát triển thêm khi có người phụ trách, điều kiện và nguồn lực rõ ràng."}]' AND seo_json='{"title":"Sáng kiến xanh | Xanh Sky First","description":"Sáng kiến là cơ hội để biến câu hỏi thực tế thành phương án có thể thử nghiệm và cải thiện. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='gioi-thieu-linh-vuc' AND title='Năm lĩnh vực hành động' AND status='published' AND blocks_json='[{"type":"heading","text":"Năm lĩnh vực định hướng những chủ đề mà Xanh có thể phát triển nội dung, tài nguyên, sáng kiến và hoạt động cộng đồng."},{"type":"paragraph","text":"Môi trường và không gian sống tập trung vào chất lượng nơi ở, rác thải, cảnh quan và cách cộng đồng sử dụng không gian chung. Giáo dục môi trường cung cấp kiến thức, công cụ học tập và cơ hội trao đổi. Lối sống và tiêu dùng bền vững giúp người đọc xem xét thói quen sử dụng tài nguyên, mua sắm, tái sử dụng và lựa chọn sản phẩm trong bối cảnh thực tế."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Đổi mới và sáng kiến xanh là không gian để đề xuất, kiểm tra và cải thiện các ý tưởng hoặc công cụ có thể giải quyết vấn đề cụ thể. Cộng đồng và phát triển bền vững chú ý đến khả năng tham gia của nhiều nhóm người, sự phù hợp với địa phương, tính công bằng và duy trì giá trị sau một chương trình. Các lĩnh vực có thể giao nhau; điều quan trọng là mỗi nội dung cần giải thích rõ vấn đề và mục tiêu chính."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Danh mục lĩnh vực không phải lời khẳng định rằng tất cả chương trình đã được triển khai. Đây là khung để tổ chức nội dung và đánh giá đề xuất trong từng giai đoạn. Một sáng kiến chỉ nên được giới thiệu như hoạt động đang thực hiện khi đã có kế hoạch được duyệt và thông tin cần thiết; ý tưởng mới cần được gắn trạng thái đề xuất hoặc đang phát triển."}]' AND seo_json='{"title":"Năm lĩnh vực hành động | Xanh Sky First","description":"Năm lĩnh vực định hướng những chủ đề mà Xanh có thể phát triển nội dung, tài nguyên, sáng kiến và hoạt động cộng đồng. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Các chủ đề dưới đây là cách tổ chức nội dung để bạn tìm thông tin thuận tiện hơn; chúng không phải danh sách thành tích hay lời khẳng định rằng mọi chương trình đều đang diễn ra."},{"type":"heading","text":"Môi trường và không gian sống"},{"type":"paragraph","text":"Các vấn đề gắn với nơi ở, chất thải, tài nguyên và chất lượng môi trường tại địa phương. Khi đọc một giải pháp, hãy xét điều kiện thực tế để thực hiện và xử lý sau đó."},{"type":"heading","text":"Giáo dục và lựa chọn bền vững"},{"type":"paragraph","text":"Tài liệu, hướng dẫn và hoạt động giúp người học hiểu bối cảnh, thử cách làm phù hợp và phân biệt thông tin có nguồn với ý kiến chưa được kiểm chứng."},{"type":"heading","text":"Đổi mới, sáng kiến và cộng đồng"},{"type":"paragraph","text":"Ý tưởng và cách phối hợp được phát triển quanh một nhu cầu cụ thể. Mỗi sáng kiến cần được đánh giá theo phạm vi, nguồn lực, rủi ro và bằng chứng thu được, không chỉ theo mức độ mới lạ."}]',seo_json='{"title":"Các lĩnh vực nội dung của Xanh Sky First","description":"Năm hướng nội dung giúp người đọc tìm tài nguyên, hoạt động và sáng kiến về môi trường và cộng đồng."}',updated_at=datetime('now') WHERE slug='gioi-thieu-linh-vuc' AND title='Năm lĩnh vực hành động' AND status='published' AND blocks_json='[{"type":"heading","text":"Năm lĩnh vực định hướng những chủ đề mà Xanh có thể phát triển nội dung, tài nguyên, sáng kiến và hoạt động cộng đồng."},{"type":"paragraph","text":"Môi trường và không gian sống tập trung vào chất lượng nơi ở, rác thải, cảnh quan và cách cộng đồng sử dụng không gian chung. Giáo dục môi trường cung cấp kiến thức, công cụ học tập và cơ hội trao đổi. Lối sống và tiêu dùng bền vững giúp người đọc xem xét thói quen sử dụng tài nguyên, mua sắm, tái sử dụng và lựa chọn sản phẩm trong bối cảnh thực tế."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Đổi mới và sáng kiến xanh là không gian để đề xuất, kiểm tra và cải thiện các ý tưởng hoặc công cụ có thể giải quyết vấn đề cụ thể. Cộng đồng và phát triển bền vững chú ý đến khả năng tham gia của nhiều nhóm người, sự phù hợp với địa phương, tính công bằng và duy trì giá trị sau một chương trình. Các lĩnh vực có thể giao nhau; điều quan trọng là mỗi nội dung cần giải thích rõ vấn đề và mục tiêu chính."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Danh mục lĩnh vực không phải lời khẳng định rằng tất cả chương trình đã được triển khai. Đây là khung để tổ chức nội dung và đánh giá đề xuất trong từng giai đoạn. Một sáng kiến chỉ nên được giới thiệu như hoạt động đang thực hiện khi đã có kế hoạch được duyệt và thông tin cần thiết; ý tưởng mới cần được gắn trạng thái đề xuất hoặc đang phát triển."}]' AND seo_json='{"title":"Năm lĩnh vực hành động | Xanh Sky First","description":"Năm lĩnh vực định hướng những chủ đề mà Xanh có thể phát triển nội dung, tài nguyên, sáng kiến và hoạt động cộng đồng. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='gioi-thieu-nguyen-tac' AND title='Bốn nguyên tắc hành động' AND status='published' AND blocks_json='[{"type":"heading","text":"Bốn nguyên tắc giúp Xanh giữ sự nhất quán giữa nhận thức, cách làm và kết quả."},{"type":"paragraph","text":"Hiểu đúng trước khi hành động giúp người tham gia đặt câu hỏi, kiểm tra nguồn và hiểu bối cảnh trước khi lựa chọn giải pháp. Hành động từ những điều có thể thực hiện yêu cầu mục tiêu, người phụ trách, cách ghi nhận và bước tổng kết rõ ràng. Kết nối để cùng tạo thay đổi nhấn mạnh chất lượng hợp tác thay vì chỉ tăng số lượng kết nối. Theo đuổi giá trị bền vững nghĩa là lưu lại kinh nghiệm, tài liệu, dữ liệu và bài học sau khi chương trình kết thúc."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Các nguyên tắc này không phải khẩu hiệu trang trí mà là tiêu chí để xem xét đề xuất, thiết kế hoạt động, biên soạn tài nguyên và cập nhật kết quả. Khi một lựa chọn chưa phù hợp với điều kiện thực tế, việc điều chỉnh phạm vi hoặc hoãn triển khai có thể có trách nhiệm hơn là cố tổ chức để tạo hình ảnh. Xanh khuyến khích người tham gia nêu câu hỏi, phản hồi có căn cứ và ghi lại những điểm chưa đạt để các lần sau làm tốt hơn."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Trong thực hành, một nguyên tắc cần được chuyển thành những câu hỏi cụ thể: vấn đề đã được hiểu đúng chưa, mục tiêu có đo lường được không, vai trò đã rõ chưa, dữ liệu có thể kiểm tra không và kết quả có thể tiếp tục được sử dụng như thế nào. Những câu hỏi này giúp nhóm tránh hành động theo cảm tính hoặc theo xu hướng ngắn hạn."}]' AND seo_json='{"title":"Bốn nguyên tắc hành động | Xanh Sky First","description":"Bốn nguyên tắc giúp Xanh giữ sự nhất quán giữa nhận thức, cách làm và kết quả. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Các nguyên tắc này giúp xem xét một hoạt động có phù hợp hay không. Chúng là tiêu chí định hướng, không thay thế việc kiểm tra dữ liệu và kết quả của từng chương trình."},{"type":"heading","text":"Hiểu vấn đề trước khi đề xuất"},{"type":"paragraph","text":"Bắt đầu từ bối cảnh và câu hỏi cần giải quyết. Kiểm tra nguồn thông tin, lắng nghe người chịu ảnh hưởng và phân biệt bằng chứng với giả định trước khi chọn giải pháp."},{"type":"heading","text":"Mỗi hoạt động có mục tiêu rõ"},{"type":"paragraph","text":"Người tham gia cần biết mình làm gì, ai phụ trách và kết quả sẽ được ghi nhận ra sao. Một hoạt động nhỏ nhưng đúng nhu cầu có thể hữu ích hơn một chương trình lớn mà không có cách đánh giá."},{"type":"heading","text":"Phối hợp có trách nhiệm"},{"type":"paragraph","text":"Thống nhất vai trò, thời hạn, điều kiện và kênh trao đổi. Tôn trọng năng lực, thời gian và giới hạn của mỗi bên; không mặc định rằng ai cũng có cùng điều kiện tham gia."},{"type":"heading","text":"Công bố đúng những gì đã biết"},{"type":"paragraph","text":"Phân biệt mục tiêu, kế hoạch, tiến độ và kết quả. Với số liệu, cần có nguồn và cách hiểu; với phần chưa được xác minh, hãy nói rõ thay vì dùng cách diễn đạt tạo cảm giác chắc chắn."}]',seo_json='{"title":"Nguyên tắc hành động | Xanh Sky First","description":"Bốn nguyên tắc biên tập và triển khai: hiểu vấn đề, làm việc có mục tiêu, phối hợp rõ ràng và ghi nhận trung thực."}',updated_at=datetime('now') WHERE slug='gioi-thieu-nguyen-tac' AND title='Bốn nguyên tắc hành động' AND status='published' AND blocks_json='[{"type":"heading","text":"Bốn nguyên tắc giúp Xanh giữ sự nhất quán giữa nhận thức, cách làm và kết quả."},{"type":"paragraph","text":"Hiểu đúng trước khi hành động giúp người tham gia đặt câu hỏi, kiểm tra nguồn và hiểu bối cảnh trước khi lựa chọn giải pháp. Hành động từ những điều có thể thực hiện yêu cầu mục tiêu, người phụ trách, cách ghi nhận và bước tổng kết rõ ràng. Kết nối để cùng tạo thay đổi nhấn mạnh chất lượng hợp tác thay vì chỉ tăng số lượng kết nối. Theo đuổi giá trị bền vững nghĩa là lưu lại kinh nghiệm, tài liệu, dữ liệu và bài học sau khi chương trình kết thúc."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Các nguyên tắc này không phải khẩu hiệu trang trí mà là tiêu chí để xem xét đề xuất, thiết kế hoạt động, biên soạn tài nguyên và cập nhật kết quả. Khi một lựa chọn chưa phù hợp với điều kiện thực tế, việc điều chỉnh phạm vi hoặc hoãn triển khai có thể có trách nhiệm hơn là cố tổ chức để tạo hình ảnh. Xanh khuyến khích người tham gia nêu câu hỏi, phản hồi có căn cứ và ghi lại những điểm chưa đạt để các lần sau làm tốt hơn."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Trong thực hành, một nguyên tắc cần được chuyển thành những câu hỏi cụ thể: vấn đề đã được hiểu đúng chưa, mục tiêu có đo lường được không, vai trò đã rõ chưa, dữ liệu có thể kiểm tra không và kết quả có thể tiếp tục được sử dụng như thế nào. Những câu hỏi này giúp nhóm tránh hành động theo cảm tính hoặc theo xu hướng ngắn hạn."}]' AND seo_json='{"title":"Bốn nguyên tắc hành động | Xanh Sky First","description":"Bốn nguyên tắc giúp Xanh giữ sự nhất quán giữa nhận thức, cách làm và kết quả. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='hoat-dong-huong-dan' AND title='Hướng dẫn tham gia hoạt động' AND status='published' AND blocks_json='[{"type":"heading","text":"Mỗi chương trình cần cung cấp hướng dẫn đủ rõ để người mới có thể chuẩn bị an toàn và chủ động."},{"type":"paragraph","text":"Trước hết, hãy đọc mục tiêu, thời gian, địa điểm và phạm vi công việc của hoạt động. Nếu chưa rõ điều kiện tham gia, hãy liên hệ đầu mối được công bố trước khi di chuyển. Người tham gia nên báo những giới hạn quan trọng liên quan đến thời gian hoặc khả năng thực hiện nhiệm vụ để nhóm điều phối có thể phân công phù hợp."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Với hoạt động ngoài trời hoặc thu gom chất thải, hãy tuân thủ hướng dẫn của người phụ trách, sử dụng trang bị phù hợp và không tự xử lý vật sắc nhọn, hóa chất, chất thải y tế hoặc các vật liệu không xác định. Không đặt mình vào tình huống nguy hiểm chỉ để hoàn thành nhiệm vụ hoặc tạo hình ảnh. Khi gặp sự cố, dừng công việc và báo người điều phối."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Sau hoạt động, hãy hỗ trợ việc thu dọn, bàn giao vật dụng và chia sẻ phản hồi trung thực. Nếu có biểu mẫu tổng kết, chỉ cung cấp thông tin mà mình biết hoặc trực tiếp quan sát. Hình ảnh cá nhân và hình ảnh của người khác cần được chia sẻ với sự tôn trọng. Những phản hồi cụ thể giúp chương trình cải thiện cách tổ chức và nâng cao trải nghiệm cho những người tham gia sau."}]' AND seo_json='{"title":"Hướng dẫn tham gia hoạt động | Xanh Sky First","description":"Mỗi chương trình cần cung cấp hướng dẫn đủ rõ để người mới có thể chuẩn bị an toàn và chủ động. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Trước khi đăng ký, hãy đọc đầy đủ mô tả hoạt động. Tên sự kiện chưa cho biết hết nhiệm vụ, địa điểm, thời lượng hoặc yêu cầu cần chuẩn bị."},{"type":"heading","text":"Kiểm tra lịch và điều kiện"},{"type":"paragraph","text":"Đối chiếu ngày, giờ, địa điểm, độ tuổi, kỹ năng, trang phục hoặc vật dụng cần có nếu được nêu. Nếu có nội dung chưa rõ, hãy hỏi đầu mối liên hệ trước khi gửi thông tin cá nhân."},{"type":"heading","text":"Chuẩn bị trong phạm vi của bạn"},{"type":"paragraph","text":"Chỉ nhận phần việc phù hợp với sức khỏe, thời gian và khả năng của mình. Với hoạt động trực tiếp, hãy làm theo hướng dẫn an toàn của người phụ trách và thông báo sớm nếu không thể tham gia như đã đăng ký."},{"type":"heading","text":"Sau hoạt động"},{"type":"paragraph","text":"Thực hiện bước bàn giao hoặc phản hồi nếu chương trình yêu cầu. Hình ảnh, lời kể và thông tin của người khác chỉ nên chia sẻ khi phù hợp với phạm vi đã thống nhất."}]',seo_json='{"title":"Hướng dẫn tham gia hoạt động | Xanh Sky First","description":"Các bước chuẩn bị trước khi đăng ký hoạt động: đọc yêu cầu, kiểm tra thời gian, xác nhận điều kiện và lưu thông tin tiếp nhận."}',updated_at=datetime('now') WHERE slug='hoat-dong-huong-dan' AND title='Hướng dẫn tham gia hoạt động' AND status='published' AND blocks_json='[{"type":"heading","text":"Mỗi chương trình cần cung cấp hướng dẫn đủ rõ để người mới có thể chuẩn bị an toàn và chủ động."},{"type":"paragraph","text":"Trước hết, hãy đọc mục tiêu, thời gian, địa điểm và phạm vi công việc của hoạt động. Nếu chưa rõ điều kiện tham gia, hãy liên hệ đầu mối được công bố trước khi di chuyển. Người tham gia nên báo những giới hạn quan trọng liên quan đến thời gian hoặc khả năng thực hiện nhiệm vụ để nhóm điều phối có thể phân công phù hợp."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Với hoạt động ngoài trời hoặc thu gom chất thải, hãy tuân thủ hướng dẫn của người phụ trách, sử dụng trang bị phù hợp và không tự xử lý vật sắc nhọn, hóa chất, chất thải y tế hoặc các vật liệu không xác định. Không đặt mình vào tình huống nguy hiểm chỉ để hoàn thành nhiệm vụ hoặc tạo hình ảnh. Khi gặp sự cố, dừng công việc và báo người điều phối."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Sau hoạt động, hãy hỗ trợ việc thu dọn, bàn giao vật dụng và chia sẻ phản hồi trung thực. Nếu có biểu mẫu tổng kết, chỉ cung cấp thông tin mà mình biết hoặc trực tiếp quan sát. Hình ảnh cá nhân và hình ảnh của người khác cần được chia sẻ với sự tôn trọng. Những phản hồi cụ thể giúp chương trình cải thiện cách tổ chức và nâng cao trải nghiệm cho những người tham gia sau."}]' AND seo_json='{"title":"Hướng dẫn tham gia hoạt động | Xanh Sky First","description":"Mỗi chương trình cần cung cấp hướng dẫn đủ rõ để người mới có thể chuẩn bị an toàn và chủ động. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='hoat-dong-lich' AND title='Lịch hoạt động' AND status='published' AND blocks_json='[{"type":"heading","text":"Lịch hoạt động chỉ công bố thông tin đã được xác nhận để người tham gia chủ động sắp xếp."},{"type":"paragraph","text":"Mỗi hoạt động nên hiển thị thời gian, địa điểm, mục tiêu, đối tượng phù hợp, yêu cầu chuẩn bị và thời hạn đăng ký khi có. Nếu thông tin vẫn đang chờ xác nhận, trang cần thể hiện trạng thái dự kiến hoặc chưa mở đăng ký. Không sử dụng ngày giả chỉ để tạo cảm giác website đang hoạt động liên tục."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Trước khi đăng ký, người tham gia nên kiểm tra hướng dẫn về di chuyển, thiết bị bảo hộ, điều kiện thời tiết hoặc các yêu cầu đặc thù. Với hoạt động ngoài trời, đơn vị tổ chức cần có người điều phối, phương án liên hệ khi phát sinh thay đổi và hướng dẫn an toàn ở mức phù hợp. Những nội dung này giúp người mới hiểu mình cần làm gì và nơi tìm trợ giúp khi cần."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Khi lịch thay đổi, thông tin mới cần được cập nhật nhất quán trên trang, biểu mẫu và thông báo đã gửi. Sau khi kết thúc, hoạt động có thể được chuyển sang trạng thái hoàn thành và bổ sung phần tổng kết đã xác minh. Lịch sử thông tin giúp cộng đồng hiểu điều gì đã diễn ra và hỗ trợ việc lập kế hoạch cho lần tiếp theo."}]' AND seo_json='{"title":"Lịch hoạt động | Xanh Sky First","description":"Lịch hoạt động chỉ công bố thông tin đã được xác nhận để người tham gia chủ động sắp xếp. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Lịch là thông tin để lập kế hoạch, không phải bảo đảm rằng mọi hoạt động vẫn diễn ra theo dự kiến. Hãy mở trang chi tiết để kiểm tra trạng thái mới nhất và hướng dẫn do chương trình công bố."},{"type":"heading","text":"Những thông tin nên kiểm tra"},{"type":"paragraph","text":"Đọc ngày, giờ, địa điểm, thời lượng, sức chứa và yêu cầu đăng ký nếu có. Với hoạt động trực tiếp, tính đến thời gian di chuyển và điều kiện tiếp cận địa điểm. Nếu thông tin chưa được nêu, đừng tự suy đoán."},{"type":"heading","text":"Khi lịch thay đổi"},{"type":"paragraph","text":"Mốc thời gian có thể thay đổi do điều kiện triển khai. Hãy theo dõi cập nhật trên trang chính thức và dùng đầu mối liên hệ khi cần xác nhận. Nếu đã đăng ký, kiểm tra email hoặc trạng thái hồ sơ theo hướng dẫn của chương trình."},{"type":"heading","text":"Phân biệt đang mở và đã kết thúc"},{"type":"paragraph","text":"Trạng thái hoạt động cho biết thông tin tại thời điểm công bố. Một hoạt động đã hoàn thành không còn là lời mời đăng ký mới; một hoạt động đang mở vẫn có thể có điều kiện riêng hoặc đã đủ sức chứa."}]',seo_json='{"title":"Lịch hoạt động | Xanh Sky First","description":"Cách đọc lịch hoạt động và kiểm tra trạng thái, thời gian, địa điểm, điều kiện tham gia trước khi lên kế hoạch."}',updated_at=datetime('now') WHERE slug='hoat-dong-lich' AND title='Lịch hoạt động' AND status='published' AND blocks_json='[{"type":"heading","text":"Lịch hoạt động chỉ công bố thông tin đã được xác nhận để người tham gia chủ động sắp xếp."},{"type":"paragraph","text":"Mỗi hoạt động nên hiển thị thời gian, địa điểm, mục tiêu, đối tượng phù hợp, yêu cầu chuẩn bị và thời hạn đăng ký khi có. Nếu thông tin vẫn đang chờ xác nhận, trang cần thể hiện trạng thái dự kiến hoặc chưa mở đăng ký. Không sử dụng ngày giả chỉ để tạo cảm giác website đang hoạt động liên tục."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Trước khi đăng ký, người tham gia nên kiểm tra hướng dẫn về di chuyển, thiết bị bảo hộ, điều kiện thời tiết hoặc các yêu cầu đặc thù. Với hoạt động ngoài trời, đơn vị tổ chức cần có người điều phối, phương án liên hệ khi phát sinh thay đổi và hướng dẫn an toàn ở mức phù hợp. Những nội dung này giúp người mới hiểu mình cần làm gì và nơi tìm trợ giúp khi cần."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Khi lịch thay đổi, thông tin mới cần được cập nhật nhất quán trên trang, biểu mẫu và thông báo đã gửi. Sau khi kết thúc, hoạt động có thể được chuyển sang trạng thái hoàn thành và bổ sung phần tổng kết đã xác minh. Lịch sử thông tin giúp cộng đồng hiểu điều gì đã diễn ra và hỗ trợ việc lập kế hoạch cho lần tiếp theo."}]' AND seo_json='{"title":"Lịch hoạt động | Xanh Sky First","description":"Lịch hoạt động chỉ công bố thông tin đã được xác nhận để người tham gia chủ động sắp xếp. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='page-co-hoi' AND title='Cơ hội dành cho người trẻ' AND status='published' AND blocks_json='[{"type":"heading","text":"Tìm cách đóng góp phù hợp với năng lực và điều kiện của bạn"},{"type":"paragraph","text":"Cơ hội tại Xanh Sky First không nhất thiết chỉ là một vị trí tình nguyện cố định. Tùy từng giai đoạn, hình thức đóng góp có thể gồm hỗ trợ nghiên cứu, viết và biên tập nội dung, thiết kế, công nghệ, tổ chức hoạt động, kết nối cộng đồng, biên soạn tài liệu hoặc đề xuất giải pháp. Mỗi cơ hội cần mô tả mục tiêu, yêu cầu, thời lượng dự kiến và đầu mối liên hệ để người quan tâm hiểu rõ trước khi đăng ký."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Không phải ai cũng có cùng quỹ thời gian, điều kiện di chuyển hay kinh nghiệm. Vì vậy, một mô tả cơ hội tốt cần phân biệt việc có thể làm từ xa với nhiệm vụ phải có mặt trực tiếp, nêu rõ phần việc bắt buộc và phần việc có thể linh hoạt, đồng thời tránh hứa hẹn lợi ích không có căn cứ. Người đăng ký nên được khuyến khích lựa chọn theo khả năng thực tế, không phải theo áp lực chứng minh sự nhiệt tình."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Với cơ hội cần kỹ năng cụ thể, Xanh có thể đề nghị người tham gia gửi ví dụ công việc, mô tả kinh nghiệm hoặc hoàn thành một bước trao đổi phù hợp. Thông tin yêu cầu phải tương xứng với nhiệm vụ và chỉ được thu thập trong phạm vi cần thiết. Kết quả tiếp nhận nên có thông báo rõ ràng; nếu chưa phù hợp ở thời điểm hiện tại, người đăng ký vẫn cần được đối xử tôn trọng."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Cơ hội chỉ được hiển thị khi đã được phê duyệt và có thông tin đủ để tham gia. Nếu số lượng tiếp nhận có giới hạn, thời hạn đăng ký hoặc điều kiện tham gia thay đổi, hệ thống phải cập nhật kịp thời. Xanh hướng đến kết nối đúng người với đúng việc, tạo trải nghiệm có ý nghĩa và giữ cho lời mời đóng góp luôn trung thực với nhu cầu thực tế."}]' AND seo_json='{"title":"Cơ hội dành cho người trẻ | Xanh Sky First","description":"Tìm cách đóng góp phù hợp với năng lực và điều kiện của bạn. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Danh sách này giúp bạn tìm những cơ hội đang được công bố. Mỗi cơ hội có phạm vi và yêu cầu riêng; không nên xem mọi vị trí là phù hợp với tất cả mọi người."},{"type":"heading","text":"Chọn theo điều kiện thực tế"},{"type":"paragraph","text":"Đối chiếu thời gian, địa điểm, kỹ năng và phần việc cần thực hiện. Nếu có yêu cầu về tuổi, chuyên môn, đào tạo hoặc có mặt trực tiếp, thông tin đó cần được nêu ở trang chi tiết."},{"type":"heading","text":"Đọc trước khi gửi thông tin"},{"type":"paragraph","text":"Hãy kiểm tra thời hạn, giấy tờ cần thiết và mục đích thu thập dữ liệu. Gửi hồ sơ là bước đề nghị được xem xét, không đồng nghĩa với việc đã được chọn hoặc được hứa hẹn quyền lợi chưa công bố."},{"type":"heading","text":"Bạn chưa thấy cơ hội phù hợp?"},{"type":"paragraph","text":"Bạn có thể đọc tài nguyên, theo dõi hoạt động hoặc gửi câu hỏi về hướng đóng góp phù hợp. Nếu danh sách hiện chưa có mục nào, hãy quay lại sau thay vì dựa trên một thông tin chưa được xuất bản."}]',seo_json='{"title":"Cơ hội tham gia | Xanh Sky First","description":"Khám phá cơ hội đã công bố và đối chiếu nhiệm vụ, thời gian, kỹ năng, địa điểm cùng điều kiện tham gia."}',updated_at=datetime('now') WHERE slug='page-co-hoi' AND title='Cơ hội dành cho người trẻ' AND status='published' AND blocks_json='[{"type":"heading","text":"Tìm cách đóng góp phù hợp với năng lực và điều kiện của bạn"},{"type":"paragraph","text":"Cơ hội tại Xanh Sky First không nhất thiết chỉ là một vị trí tình nguyện cố định. Tùy từng giai đoạn, hình thức đóng góp có thể gồm hỗ trợ nghiên cứu, viết và biên tập nội dung, thiết kế, công nghệ, tổ chức hoạt động, kết nối cộng đồng, biên soạn tài liệu hoặc đề xuất giải pháp. Mỗi cơ hội cần mô tả mục tiêu, yêu cầu, thời lượng dự kiến và đầu mối liên hệ để người quan tâm hiểu rõ trước khi đăng ký."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Không phải ai cũng có cùng quỹ thời gian, điều kiện di chuyển hay kinh nghiệm. Vì vậy, một mô tả cơ hội tốt cần phân biệt việc có thể làm từ xa với nhiệm vụ phải có mặt trực tiếp, nêu rõ phần việc bắt buộc và phần việc có thể linh hoạt, đồng thời tránh hứa hẹn lợi ích không có căn cứ. Người đăng ký nên được khuyến khích lựa chọn theo khả năng thực tế, không phải theo áp lực chứng minh sự nhiệt tình."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Với cơ hội cần kỹ năng cụ thể, Xanh có thể đề nghị người tham gia gửi ví dụ công việc, mô tả kinh nghiệm hoặc hoàn thành một bước trao đổi phù hợp. Thông tin yêu cầu phải tương xứng với nhiệm vụ và chỉ được thu thập trong phạm vi cần thiết. Kết quả tiếp nhận nên có thông báo rõ ràng; nếu chưa phù hợp ở thời điểm hiện tại, người đăng ký vẫn cần được đối xử tôn trọng."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Cơ hội chỉ được hiển thị khi đã được phê duyệt và có thông tin đủ để tham gia. Nếu số lượng tiếp nhận có giới hạn, thời hạn đăng ký hoặc điều kiện tham gia thay đổi, hệ thống phải cập nhật kịp thời. Xanh hướng đến kết nối đúng người với đúng việc, tạo trải nghiệm có ý nghĩa và giữ cho lời mời đóng góp luôn trung thực với nhu cầu thực tế."}]' AND seo_json='{"title":"Cơ hội dành cho người trẻ | Xanh Sky First","description":"Tìm cách đóng góp phù hợp với năng lực và điều kiện của bạn. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='page-con-nguoi' AND title='Con người Xanh' AND status='published' AND blocks_json='[{"type":"heading","text":"Tôn trọng đóng góp, vai trò và giới hạn của mỗi người"},{"type":"paragraph","text":"Xanh Sky First nhìn nhận con người là một phần quan trọng của quá trình tạo ra thay đổi, nhưng không xem số lượng thành viên là thước đo duy nhất cho sức mạnh cộng đồng. Một môi trường đóng góp lành mạnh cần mục tiêu dễ hiểu, vai trò rõ ràng, cơ chế trao đổi phù hợp và sự tôn trọng giữa những người tham gia. Người mới có thể học hỏi; người có kinh nghiệm có thể hướng dẫn; người có chuyên môn có thể đóng góp trong phạm vi đã thống nhất."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Thông tin giới thiệu nhân sự chỉ được công khai khi chính người liên quan đã đồng ý và dữ liệu đã được xác nhận. Chức danh, kinh nghiệm, hình ảnh và mô tả vai trò phải phản ánh đúng thực tế, tránh tạo ra ấn tượng về bộ máy hoặc đội ngũ chưa tồn tại. Mỗi hồ sơ nên tập trung vào phần thông tin có ích cho cộng đồng, thay vì công bố dữ liệu riêng tư không cần thiết."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Khi phối hợp trong nhóm, Xanh khuyến khích trao đổi tôn trọng, phân công phù hợp với năng lực và thời gian, phản hồi dựa trên hành vi hoặc kết quả công việc thay vì công kích cá nhân. Các nhiệm vụ cần được giao kèm mục tiêu, đầu ra và người hỗ trợ khi cần. Nếu một người không thể tiếp tục, việc bàn giao rõ ràng giúp công việc không phụ thuộc hoàn toàn vào một cá nhân."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Cộng đồng bền vững cũng cần quan tâm đến an toàn, quyền riêng tư và sự khác biệt giữa các thành viên. Thông tin hồ sơ chỉ được tiếp cận theo quyền được cấp; hình ảnh và câu chuyện cá nhân cần có căn cứ sử dụng phù hợp. Xanh hướng đến ghi nhận công bằng những đóng góp thực tế, chia sẻ bài học hữu ích và xây dựng môi trường nơi mọi người có thể đóng góp mà không bị gây áp lực phải thể hiện thành tích."}]' AND seo_json='{"title":"Con người Xanh | Xanh Sky First","description":"Tôn trọng đóng góp, vai trò và giới hạn của mỗi người. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Khu vực này giới thiệu những hồ sơ đã được bật công khai. Thông tin cá nhân chỉ xuất hiện trong phạm vi cần cho mục đích giới thiệu và theo thiết lập công khai của từng hồ sơ."},{"type":"heading","text":"Vai trò hơn là danh xưng"},{"type":"paragraph","text":"Hồ sơ hữu ích khi giúp người đọc hiểu người đó phụ trách hoặc đóng góp ở lĩnh vực nào. Chức danh, mốc thời gian và mô tả cần được kiểm tra trước khi xuất bản, nhất là khi vai trò thay đổi."},{"type":"heading","text":"Tôn trọng quyền riêng tư"},{"type":"paragraph","text":"Không phải dữ liệu nội bộ nào cũng phù hợp để hiển thị. Ảnh, câu chuyện và thông tin liên hệ cần có căn cứ sử dụng phù hợp; hồ sơ không công khai sẽ không được tự đưa lên danh sách."},{"type":"heading","text":"Cần cập nhật hồ sơ?"},{"type":"paragraph","text":"Người có hồ sơ hoặc người phụ trách có thể liên hệ qua kênh chính thức để đề nghị kiểm tra thông tin. Yêu cầu liên quan đến dữ liệu riêng tư có thể cần bước xác minh để bảo vệ đúng người."}]',seo_json='{"title":"Con người Xanh | Xanh Sky First","description":"Tìm hiểu hồ sơ công khai, vai trò và lĩnh vực đóng góp của những người đã đồng ý giới thiệu trên website."}',updated_at=datetime('now') WHERE slug='page-con-nguoi' AND title='Con người Xanh' AND status='published' AND blocks_json='[{"type":"heading","text":"Tôn trọng đóng góp, vai trò và giới hạn của mỗi người"},{"type":"paragraph","text":"Xanh Sky First nhìn nhận con người là một phần quan trọng của quá trình tạo ra thay đổi, nhưng không xem số lượng thành viên là thước đo duy nhất cho sức mạnh cộng đồng. Một môi trường đóng góp lành mạnh cần mục tiêu dễ hiểu, vai trò rõ ràng, cơ chế trao đổi phù hợp và sự tôn trọng giữa những người tham gia. Người mới có thể học hỏi; người có kinh nghiệm có thể hướng dẫn; người có chuyên môn có thể đóng góp trong phạm vi đã thống nhất."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Thông tin giới thiệu nhân sự chỉ được công khai khi chính người liên quan đã đồng ý và dữ liệu đã được xác nhận. Chức danh, kinh nghiệm, hình ảnh và mô tả vai trò phải phản ánh đúng thực tế, tránh tạo ra ấn tượng về bộ máy hoặc đội ngũ chưa tồn tại. Mỗi hồ sơ nên tập trung vào phần thông tin có ích cho cộng đồng, thay vì công bố dữ liệu riêng tư không cần thiết."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Khi phối hợp trong nhóm, Xanh khuyến khích trao đổi tôn trọng, phân công phù hợp với năng lực và thời gian, phản hồi dựa trên hành vi hoặc kết quả công việc thay vì công kích cá nhân. Các nhiệm vụ cần được giao kèm mục tiêu, đầu ra và người hỗ trợ khi cần. Nếu một người không thể tiếp tục, việc bàn giao rõ ràng giúp công việc không phụ thuộc hoàn toàn vào một cá nhân."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Cộng đồng bền vững cũng cần quan tâm đến an toàn, quyền riêng tư và sự khác biệt giữa các thành viên. Thông tin hồ sơ chỉ được tiếp cận theo quyền được cấp; hình ảnh và câu chuyện cá nhân cần có căn cứ sử dụng phù hợp. Xanh hướng đến ghi nhận công bằng những đóng góp thực tế, chia sẻ bài học hữu ích và xây dựng môi trường nơi mọi người có thể đóng góp mà không bị gây áp lực phải thể hiện thành tích."}]' AND seo_json='{"title":"Con người Xanh | Xanh Sky First","description":"Tôn trọng đóng góp, vai trò và giới hạn của mỗi người. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='page-du-an' AND title='Dự án & sáng kiến' AND status='published' AND blocks_json='[{"type":"heading","text":"Giải pháp được phát triển từ vấn đề thực tế"},{"type":"paragraph","text":"Các dự án của Xanh Sky First được định hướng bắt đầu từ một vấn đề cụ thể, một nhóm thụ hưởng có thể xác định và một mục tiêu phù hợp với nguồn lực hiện có. Thay vì chỉ đặt tên cho một chiến dịch rồi tìm cách lấp đầy lịch hoạt động, mỗi ý tưởng cần trải qua bước tìm hiểu bối cảnh, phân tích nhu cầu, xác định rủi ro và lựa chọn phương pháp triển khai."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Một đề xuất tốt cần giải thích vì sao vấn đề đáng quan tâm, ai chịu ảnh hưởng, những giải pháp nào đã được thử nghiệm và điều gì khiến phương án đang đề xuất phù hợp. Khi chủ đề liên quan đến môi trường, nhóm thực hiện cần phân biệt giữa việc tạo ra hình ảnh đẹp và thay đổi có ý nghĩa; đồng thời cân nhắc tính an toàn, tác động lâu dài, khả năng duy trì và các hệ quả ngoài dự kiến."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Các dự án có thể bao gồm tài nguyên giáo dục, nghiên cứu cộng đồng, giải pháp giảm chất thải, công cụ hỗ trợ hành vi bền vững, hoạt động thử nghiệm tại địa phương hoặc sáng kiến hợp tác. Hình thức chỉ được lựa chọn sau khi hiểu vấn đề. Thành viên có thể đóng góp bằng nghiên cứu, thiết kế, nội dung, công nghệ, hậu cần, điều phối hoặc đánh giá, tùy năng lực và vai trò đã thống nhất."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Thông tin dự án cần được công bố theo mức độ sẵn sàng: đề xuất, đang chuẩn bị, đang triển khai, đã hoàn thành hoặc tạm dừng. Mục tiêu, tiến độ, thay đổi phạm vi và kết quả phải được cập nhật đúng thực tế. Nếu dự án chưa có đối tác, ngân sách, địa điểm hay số liệu xác nhận, website phải nói rõ điều đó thay vì khiến người đọc hiểu nhầm rằng dự án đã triển khai."}]' AND seo_json='{"title":"Dự án & sáng kiến | Xanh Sky First","description":"Giải pháp được phát triển từ vấn đề thực tế. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Mỗi dự án cần trả lời vấn đề nào đang được giải quyết, ai chịu ảnh hưởng và phạm vi thực hiện đến đâu. Danh sách này chỉ hiển thị nội dung được xuất bản; thông tin chi tiết của từng dự án là căn cứ để hiểu tình trạng cụ thể."},{"type":"heading","text":"Đọc mục tiêu cùng giới hạn"},{"type":"paragraph","text":"Mục tiêu là điều dự án hướng tới, không phải kết quả đã đạt. Hãy xem phần mô tả, mốc thời gian, địa điểm và tài liệu liên quan để phân biệt kế hoạch với phần việc đã hoàn thành."},{"type":"heading","text":"Kết quả cần có nguồn"},{"type":"paragraph","text":"Số liệu, câu chuyện và hình ảnh nên gắn với thời điểm, phương pháp ghi nhận và quyền sử dụng phù hợp. Nếu một kết quả đang chờ xác minh, nội dung nên nói rõ điều đó."},{"type":"heading","text":"Tìm hiểu cách đồng hành"},{"type":"paragraph","text":"Cơ hội tham gia, nếu có, sẽ được nêu riêng theo điều kiện của dự án. Bạn có thể đọc tài nguyên nền hoặc liên hệ để hỏi về phạm vi đang mở, thay vì tự suy đoán từ tên chương trình."}]',seo_json='{"title":"Dự án và sáng kiến | Xanh Sky First","description":"Theo dõi các dự án và sáng kiến đã công bố qua mục tiêu, phạm vi, tiến độ, nguồn lực và kết quả có căn cứ."}',updated_at=datetime('now') WHERE slug='page-du-an' AND title='Dự án & sáng kiến' AND status='published' AND blocks_json='[{"type":"heading","text":"Giải pháp được phát triển từ vấn đề thực tế"},{"type":"paragraph","text":"Các dự án của Xanh Sky First được định hướng bắt đầu từ một vấn đề cụ thể, một nhóm thụ hưởng có thể xác định và một mục tiêu phù hợp với nguồn lực hiện có. Thay vì chỉ đặt tên cho một chiến dịch rồi tìm cách lấp đầy lịch hoạt động, mỗi ý tưởng cần trải qua bước tìm hiểu bối cảnh, phân tích nhu cầu, xác định rủi ro và lựa chọn phương pháp triển khai."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Một đề xuất tốt cần giải thích vì sao vấn đề đáng quan tâm, ai chịu ảnh hưởng, những giải pháp nào đã được thử nghiệm và điều gì khiến phương án đang đề xuất phù hợp. Khi chủ đề liên quan đến môi trường, nhóm thực hiện cần phân biệt giữa việc tạo ra hình ảnh đẹp và thay đổi có ý nghĩa; đồng thời cân nhắc tính an toàn, tác động lâu dài, khả năng duy trì và các hệ quả ngoài dự kiến."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Các dự án có thể bao gồm tài nguyên giáo dục, nghiên cứu cộng đồng, giải pháp giảm chất thải, công cụ hỗ trợ hành vi bền vững, hoạt động thử nghiệm tại địa phương hoặc sáng kiến hợp tác. Hình thức chỉ được lựa chọn sau khi hiểu vấn đề. Thành viên có thể đóng góp bằng nghiên cứu, thiết kế, nội dung, công nghệ, hậu cần, điều phối hoặc đánh giá, tùy năng lực và vai trò đã thống nhất."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Thông tin dự án cần được công bố theo mức độ sẵn sàng: đề xuất, đang chuẩn bị, đang triển khai, đã hoàn thành hoặc tạm dừng. Mục tiêu, tiến độ, thay đổi phạm vi và kết quả phải được cập nhật đúng thực tế. Nếu dự án chưa có đối tác, ngân sách, địa điểm hay số liệu xác nhận, website phải nói rõ điều đó thay vì khiến người đọc hiểu nhầm rằng dự án đã triển khai."}]' AND seo_json='{"title":"Dự án & sáng kiến | Xanh Sky First","description":"Giải pháp được phát triển từ vấn đề thực tế. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='page-hoat-dong' AND title='Hoạt động & sự kiện' AND status='published' AND blocks_json='[{"type":"heading","text":"Mỗi hoạt động cần có mục tiêu, người phụ trách và kết quả rõ ràng"},{"type":"paragraph","text":"Khu vực Hoạt động tập hợp những chương trình cộng đồng, buổi chia sẻ, hoạt động giáo dục, sự kiện hoặc hình thức tham gia khác đã được Xanh Sky First công bố. Mỗi thông tin hoạt động cần giúp người đọc nhanh chóng hiểu mục đích, đối tượng phù hợp, thời gian, địa điểm, yêu cầu chuẩn bị và cách đăng ký. Những thông tin chưa xác nhận không được trình bày như lịch đã chốt."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Một hoạt động được chuẩn bị có trách nhiệm cần xác định người chịu trách nhiệm, điều phối an toàn, cách liên hệ khi phát sinh thay đổi và phương án phù hợp với điều kiện thực tế. Với các hoạt động ngoài trời hoặc có thu gom chất thải, nội dung hướng dẫn nên nêu rõ phạm vi, thiết bị bảo hộ, cách phân loại và bàn giao chất thải, cũng như giới hạn công việc mà người tham gia có thể thực hiện."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Thông tin trước hoạt động nên được cập nhật kịp thời khi thời gian hoặc địa điểm thay đổi. Sau khi kết thúc, phần tổng kết cần ghi nhận diễn biến, kinh nghiệm, điểm còn hạn chế và dữ liệu có thể kiểm chứng. Hình ảnh minh họa không thay thế cho việc xác minh số người tham gia, khối lượng chất thải hay kết quả thực tế; các con số phải có nguồn và người xác nhận phù hợp."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Xanh hướng đến trải nghiệm tham gia dễ hiểu, tôn trọng người đóng góp và phù hợp với các mức độ năng lực khác nhau. Người mới cần được cung cấp hướng dẫn rõ ràng; người có chuyên môn cần biết phạm vi nhiệm vụ; người không thể tham dự trực tiếp vẫn có thể đóng góp ở những phần việc phù hợp khi chương trình cho phép. Hoạt động chỉ được mở đăng ký khi có thông tin đủ để người tham gia đưa ra lựa chọn có hiểu biết."}]' AND seo_json='{"title":"Hoạt động & sự kiện | Xanh Sky First","description":"Mỗi hoạt động cần có mục tiêu, người phụ trách và kết quả rõ ràng. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Trang hoạt động tập hợp những buổi gặp gỡ, chương trình và sự kiện đã được công bố. Trạng thái và lịch có thể khác nhau giữa từng mục, vì vậy hãy mở chi tiết trước khi lên kế hoạch."},{"type":"heading","text":"Thông tin cần có trước khi tham gia"},{"type":"paragraph","text":"Kiểm tra thời gian, địa điểm, thời lượng, yêu cầu chuẩn bị, đối tượng phù hợp và cách đăng ký. Nếu hoạt động cần có mặt trực tiếp hoặc có giới hạn sức chứa, trang chi tiết cần nêu rõ điều đó."},{"type":"heading","text":"Cập nhật khi có thay đổi"},{"type":"paragraph","text":"Mưa, địa điểm, nhân sự hoặc điều kiện triển khai có thể khiến lịch phải điều chỉnh. Hãy theo dõi cập nhật chính thức; nếu đã gửi hồ sơ, lưu mã tiếp nhận và kiểm tra kênh liên hệ đã đăng ký."},{"type":"heading","text":"Sau khi hoạt động kết thúc"},{"type":"paragraph","text":"Nội dung tổng kết nên phân biệt phần việc đã thực hiện với mục tiêu ban đầu và nêu nguồn cho các con số được công bố. Việc có một bài viết hoặc hình ảnh không tự nó chứng minh toàn bộ tác động của hoạt động."}]',seo_json='{"title":"Hoạt động và sự kiện | Xanh Sky First","description":"Xem lịch, địa điểm, trạng thái và hướng dẫn tham gia những hoạt động đã được công bố."}',updated_at=datetime('now') WHERE slug='page-hoat-dong' AND title='Hoạt động & sự kiện' AND status='published' AND blocks_json='[{"type":"heading","text":"Mỗi hoạt động cần có mục tiêu, người phụ trách và kết quả rõ ràng"},{"type":"paragraph","text":"Khu vực Hoạt động tập hợp những chương trình cộng đồng, buổi chia sẻ, hoạt động giáo dục, sự kiện hoặc hình thức tham gia khác đã được Xanh Sky First công bố. Mỗi thông tin hoạt động cần giúp người đọc nhanh chóng hiểu mục đích, đối tượng phù hợp, thời gian, địa điểm, yêu cầu chuẩn bị và cách đăng ký. Những thông tin chưa xác nhận không được trình bày như lịch đã chốt."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Một hoạt động được chuẩn bị có trách nhiệm cần xác định người chịu trách nhiệm, điều phối an toàn, cách liên hệ khi phát sinh thay đổi và phương án phù hợp với điều kiện thực tế. Với các hoạt động ngoài trời hoặc có thu gom chất thải, nội dung hướng dẫn nên nêu rõ phạm vi, thiết bị bảo hộ, cách phân loại và bàn giao chất thải, cũng như giới hạn công việc mà người tham gia có thể thực hiện."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Thông tin trước hoạt động nên được cập nhật kịp thời khi thời gian hoặc địa điểm thay đổi. Sau khi kết thúc, phần tổng kết cần ghi nhận diễn biến, kinh nghiệm, điểm còn hạn chế và dữ liệu có thể kiểm chứng. Hình ảnh minh họa không thay thế cho việc xác minh số người tham gia, khối lượng chất thải hay kết quả thực tế; các con số phải có nguồn và người xác nhận phù hợp."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Xanh hướng đến trải nghiệm tham gia dễ hiểu, tôn trọng người đóng góp và phù hợp với các mức độ năng lực khác nhau. Người mới cần được cung cấp hướng dẫn rõ ràng; người có chuyên môn cần biết phạm vi nhiệm vụ; người không thể tham dự trực tiếp vẫn có thể đóng góp ở những phần việc phù hợp khi chương trình cho phép. Hoạt động chỉ được mở đăng ký khi có thông tin đủ để người tham gia đưa ra lựa chọn có hiểu biết."}]' AND seo_json='{"title":"Hoạt động & sự kiện | Xanh Sky First","description":"Mỗi hoạt động cần có mục tiêu, người phụ trách và kết quả rõ ràng. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='page-tai-nguyen' AND title='Kiến thức & tài nguyên' AND status='published' AND blocks_json='[{"type":"heading","text":"Hiểu vấn đề tốt hơn để lựa chọn hành động phù hợp"},{"type":"paragraph","text":"Thư viện Xanh được định hướng là nơi tập hợp tài liệu, hướng dẫn, bài giải thích, công cụ và nguồn tham khảo giúp người đọc tiếp cận vấn đề môi trường theo cách rõ ràng hơn. Tài nguyên nên bắt đầu từ câu hỏi thật mà người đọc thường gặp, giải thích thuật ngữ khi cần và trình bày đủ bối cảnh để tránh biến một lời khuyên đơn giản thành quy tắc áp dụng cho mọi hoàn cảnh."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Nội dung môi trường thường liên quan đến nhiều yếu tố: hành vi tiêu dùng, hạ tầng thu gom, điều kiện địa phương, công nghệ, kinh tế và chính sách. Vì thế, khi đưa ra khuyến nghị, tài liệu cần phân biệt thông tin đã có bằng chứng với góc nhìn hoặc đề xuất. Nguồn tham khảo nên được ghi nhận rõ ràng; ngày cập nhật cần thể hiện khi thông tin có thể thay đổi theo thời gian."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Tài nguyên có thể phục vụ nhiều nhóm người đọc, từ học sinh, sinh viên đến người điều phối hoạt động, giáo viên, nhóm cộng đồng hoặc người đang tìm cách thay đổi thói quen. Mỗi tài liệu nên nêu đối tượng phù hợp, cách sử dụng, điều kiện cần biết và giới hạn của nội dung. Các mẫu biểu, checklist và hướng dẫn thực hành cần có ngôn ngữ dễ hiểu, dễ tiếp cận và có thể điều chỉnh cho bối cảnh thực tế."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Thư viện không chỉ là nơi lưu trữ tệp mà còn cần được cập nhật, phân loại và rà soát. Khi tài liệu lỗi thời hoặc có thông tin cần hiệu chỉnh, người quản trị nên cập nhật phiên bản và giữ lại dấu vết thay đổi. Xanh khuyến khích việc chia sẻ tài nguyên có quyền sử dụng phù hợp và tôn trọng công sức của tác giả, đồng thời không trình bày nội dung tham khảo như kết quả nghiên cứu do Xanh tự thực hiện nếu không đúng."}]' AND seo_json='{"title":"Kiến thức & tài nguyên | Xanh Sky First","description":"Hiểu vấn đề tốt hơn để lựa chọn hành động phù hợp. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Thư viện tập hợp các tài liệu giúp người đọc tìm hiểu chủ đề trước khi lựa chọn hoặc thử một cách làm. Mỗi tài nguyên nên cho biết nội dung dành cho ai, dùng trong bối cảnh nào và có giới hạn gì."},{"type":"heading","text":"Đánh giá nguồn trước khi áp dụng"},{"type":"paragraph","text":"Kiểm tra tác giả hoặc đơn vị phát hành, thời điểm cập nhật, nguồn tham khảo và điều kiện áp dụng. Hướng dẫn chung có thể không phù hợp với mọi địa phương, thiết bị hoặc nhóm người dùng."},{"type":"heading","text":"Sử dụng và chia sẻ có trách nhiệm"},{"type":"paragraph","text":"Tôn trọng bản quyền, giấy phép và yêu cầu ghi nguồn. Nếu tài liệu được dùng trong lớp học hay hoạt động cộng đồng, hãy kiểm tra mức độ phù hợp với người tham gia và cung cấp ngữ cảnh cần thiết."},{"type":"heading","text":"Góp ý để tài liệu hữu ích hơn"},{"type":"paragraph","text":"Nếu phát hiện liên kết hỏng, thông tin đã cũ hoặc hướng dẫn chưa rõ, hãy gửi phản hồi qua trang Liên hệ kèm tên tài liệu và vị trí cần kiểm tra."}]',seo_json='{"title":"Thư viện Xanh | Tài nguyên và hướng dẫn","description":"Tìm tài liệu và hướng dẫn, kiểm tra nguồn, thời điểm cập nhật, phạm vi sử dụng và mức độ phù hợp của từng tài nguyên."}',updated_at=datetime('now') WHERE slug='page-tai-nguyen' AND title='Kiến thức & tài nguyên' AND status='published' AND blocks_json='[{"type":"heading","text":"Hiểu vấn đề tốt hơn để lựa chọn hành động phù hợp"},{"type":"paragraph","text":"Thư viện Xanh được định hướng là nơi tập hợp tài liệu, hướng dẫn, bài giải thích, công cụ và nguồn tham khảo giúp người đọc tiếp cận vấn đề môi trường theo cách rõ ràng hơn. Tài nguyên nên bắt đầu từ câu hỏi thật mà người đọc thường gặp, giải thích thuật ngữ khi cần và trình bày đủ bối cảnh để tránh biến một lời khuyên đơn giản thành quy tắc áp dụng cho mọi hoàn cảnh."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Nội dung môi trường thường liên quan đến nhiều yếu tố: hành vi tiêu dùng, hạ tầng thu gom, điều kiện địa phương, công nghệ, kinh tế và chính sách. Vì thế, khi đưa ra khuyến nghị, tài liệu cần phân biệt thông tin đã có bằng chứng với góc nhìn hoặc đề xuất. Nguồn tham khảo nên được ghi nhận rõ ràng; ngày cập nhật cần thể hiện khi thông tin có thể thay đổi theo thời gian."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Tài nguyên có thể phục vụ nhiều nhóm người đọc, từ học sinh, sinh viên đến người điều phối hoạt động, giáo viên, nhóm cộng đồng hoặc người đang tìm cách thay đổi thói quen. Mỗi tài liệu nên nêu đối tượng phù hợp, cách sử dụng, điều kiện cần biết và giới hạn của nội dung. Các mẫu biểu, checklist và hướng dẫn thực hành cần có ngôn ngữ dễ hiểu, dễ tiếp cận và có thể điều chỉnh cho bối cảnh thực tế."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Thư viện không chỉ là nơi lưu trữ tệp mà còn cần được cập nhật, phân loại và rà soát. Khi tài liệu lỗi thời hoặc có thông tin cần hiệu chỉnh, người quản trị nên cập nhật phiên bản và giữ lại dấu vết thay đổi. Xanh khuyến khích việc chia sẻ tài nguyên có quyền sử dụng phù hợp và tôn trọng công sức của tác giả, đồng thời không trình bày nội dung tham khảo như kết quả nghiên cứu do Xanh tự thực hiện nếu không đúng."}]' AND seo_json='{"title":"Kiến thức & tài nguyên | Xanh Sky First","description":"Hiểu vấn đề tốt hơn để lựa chọn hành động phù hợp. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='page-tham-gia' AND title='Tham gia cùng Xanh' AND status='published' AND blocks_json='[{"type":"heading","text":"Chọn một cách bắt đầu phù hợp với bạn"},{"type":"paragraph","text":"Bạn không cần có sẵn kinh nghiệm môi trường để tìm hiểu và bắt đầu đóng góp cùng Xanh Sky First. Tùy chương trình đang được công bố, người quan tâm có thể tham gia hoạt động, đăng ký cơ hội, đóng góp chuyên môn, chia sẻ tài nguyên, gửi đề xuất sáng kiến hoặc nhận thông tin qua newsletter. Mỗi lựa chọn nên đi kèm phần mô tả rõ ràng để bạn hiểu mình đang đăng ký điều gì và thông tin được sử dụng ra sao."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Trước khi gửi biểu mẫu, hãy đọc các yêu cầu về thời gian, địa điểm, điều kiện tham gia và nội dung đồng ý. Chỉ cung cấp các thông tin cần thiết cho mục đích đã nêu; không gửi tài liệu nhạy cảm nếu biểu mẫu không yêu cầu. Nếu chưa thể tham gia trực tiếp, bạn có thể tìm những phần việc phù hợp hơn với khả năng hoặc theo dõi tài nguyên để chuẩn bị trước khi có cơ hội phù hợp."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Mỗi biểu mẫu đang mở cần hiển thị tên chương trình, mô tả, trạng thái tiếp nhận và thời hạn nếu có. Sau khi gửi thành công, hệ thống sẽ thông báo và cung cấp mã hồ sơ khi quy trình có hỗ trợ. Người đăng ký nên lưu mã để tra cứu trạng thái. Việc gửi hồ sơ không đồng nghĩa với việc tự động được chấp nhận; kết quả phụ thuộc vào thông tin, yêu cầu của chương trình và bước xử lý của người phụ trách."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Xanh hướng đến quy trình tiếp nhận tôn trọng người đăng ký. Thông tin hồ sơ được giới hạn cho người có quyền xử lý, không công khai lên website. Khi có cập nhật trạng thái, người gửi cần nhận được thông báo phù hợp nếu chức năng đó đã được cấu hình. Nếu thay đổi kế hoạch, người tham gia nên dùng kênh liên hệ được công bố để thông báo, thay vì cảm thấy phải duy trì một cam kết vượt quá điều kiện của mình."}]' AND seo_json='{"title":"Tham gia cùng Xanh | Xanh Sky First","description":"Chọn một cách bắt đầu phù hợp với bạn. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Các biểu mẫu được công bố ở khu vực này phục vụ những mục đích khác nhau, như đăng ký hoạt động hoặc gửi đề xuất. Hãy chọn đúng biểu mẫu thay vì gửi một hồ sơ chung cho mọi nhu cầu."},{"type":"heading","text":"Trước khi điền"},{"type":"paragraph","text":"Đọc mục đích tiếp nhận, điều kiện tham gia, thời hạn và các trường bắt buộc. Chỉ chuẩn bị tài liệu được yêu cầu; không cung cấp thêm dữ liệu riêng tư nếu biểu mẫu không cần."},{"type":"heading","text":"Sau khi nhấn gửi"},{"type":"paragraph","text":"Chỉ coi hồ sơ đã được gửi khi hệ thống hiển thị xác nhận tiếp nhận và mã hồ sơ nếu có. Hãy lưu mã này để tra cứu. Việc gửi hồ sơ không bảo đảm sẽ được chọn; người phụ trách có thể cần thời gian xem xét."},{"type":"heading","text":"Cần hỗ trợ?"},{"type":"paragraph","text":"Nếu chưa rõ một câu hỏi hoặc gặp lỗi khi gửi, liên hệ qua trang Liên hệ và nêu tên biểu mẫu cùng mô tả vấn đề. Không gửi mật khẩu hoặc mã xác thực qua email hay phần ghi chú."}]',seo_json='{"title":"Tham gia cùng Xanh Sky First","description":"Tìm hiểu các biểu mẫu đang mở, điều kiện đăng ký, dữ liệu cần cung cấp và cách theo dõi hồ sơ sau khi gửi."}',updated_at=datetime('now') WHERE slug='page-tham-gia' AND title='Tham gia cùng Xanh' AND status='published' AND blocks_json='[{"type":"heading","text":"Chọn một cách bắt đầu phù hợp với bạn"},{"type":"paragraph","text":"Bạn không cần có sẵn kinh nghiệm môi trường để tìm hiểu và bắt đầu đóng góp cùng Xanh Sky First. Tùy chương trình đang được công bố, người quan tâm có thể tham gia hoạt động, đăng ký cơ hội, đóng góp chuyên môn, chia sẻ tài nguyên, gửi đề xuất sáng kiến hoặc nhận thông tin qua newsletter. Mỗi lựa chọn nên đi kèm phần mô tả rõ ràng để bạn hiểu mình đang đăng ký điều gì và thông tin được sử dụng ra sao."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Trước khi gửi biểu mẫu, hãy đọc các yêu cầu về thời gian, địa điểm, điều kiện tham gia và nội dung đồng ý. Chỉ cung cấp các thông tin cần thiết cho mục đích đã nêu; không gửi tài liệu nhạy cảm nếu biểu mẫu không yêu cầu. Nếu chưa thể tham gia trực tiếp, bạn có thể tìm những phần việc phù hợp hơn với khả năng hoặc theo dõi tài nguyên để chuẩn bị trước khi có cơ hội phù hợp."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Mỗi biểu mẫu đang mở cần hiển thị tên chương trình, mô tả, trạng thái tiếp nhận và thời hạn nếu có. Sau khi gửi thành công, hệ thống sẽ thông báo và cung cấp mã hồ sơ khi quy trình có hỗ trợ. Người đăng ký nên lưu mã để tra cứu trạng thái. Việc gửi hồ sơ không đồng nghĩa với việc tự động được chấp nhận; kết quả phụ thuộc vào thông tin, yêu cầu của chương trình và bước xử lý của người phụ trách."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Xanh hướng đến quy trình tiếp nhận tôn trọng người đăng ký. Thông tin hồ sơ được giới hạn cho người có quyền xử lý, không công khai lên website. Khi có cập nhật trạng thái, người gửi cần nhận được thông báo phù hợp nếu chức năng đó đã được cấu hình. Nếu thay đổi kế hoạch, người tham gia nên dùng kênh liên hệ được công bố để thông báo, thay vì cảm thấy phải duy trì một cam kết vượt quá điều kiện của mình."}]' AND seo_json='{"title":"Tham gia cùng Xanh | Xanh Sky First","description":"Chọn một cách bắt đầu phù hợp với bạn. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='page-tin-tuc' AND title='Tin tức & câu chuyện' AND status='published' AND blocks_json='[{"type":"heading","text":"Thông tin có bối cảnh, câu chuyện có sự tôn trọng"},{"type":"paragraph","text":"Tin tức và câu chuyện là nơi Xanh Sky First chia sẻ những cập nhật đã được kiểm tra, kiến thức liên quan đến môi trường, bài học từ quá trình chuẩn bị hoặc triển khai, cùng những góc nhìn hữu ích từ cộng đồng. Mỗi bài cần giúp người đọc phân biệt đâu là thông tin, đâu là ý kiến và đâu là định hướng đang được xem xét. Tiêu đề cần chính xác, không phóng đại sự kiện hoặc tạo cảm giác có thành tích chưa được xác minh."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Với bài viết về hoạt động, nội dung nên nêu bối cảnh, mục tiêu, người tổ chức, thời gian và kết quả ở mức đã có căn cứ. Hình ảnh cần có nguồn hợp lệ và mô tả phù hợp; người xuất hiện trong ảnh phải được tôn trọng quyền riêng tư. Không dùng ảnh minh họa để khiến người đọc tưởng rằng Xanh đã tổ chức một hoạt động chưa diễn ra. Khi bài viết nói về dữ liệu, phải cho biết đơn vị, kỳ thống kê và cách hiểu chỉ số."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Câu chuyện cộng đồng cần được kể có sự đồng thuận, không tiết lộ thông tin riêng tư hoặc khai thác khó khăn của người khác chỉ để tạo cảm xúc. Trích dẫn cần đúng ngữ cảnh; nội dung biên tập không làm thay đổi ý nghĩa lời nói. Khi có thông tin sai hoặc cần cập nhật, bài viết phải có quy trình sửa đổi minh bạch để người đọc hiểu phần nào đã thay đổi và vì sao."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Xanh ưu tiên nội dung có thể giúp người đọc hiểu sâu hơn hoặc đưa ra lựa chọn tốt hơn, không chỉ nội dung có khả năng thu hút tương tác ngắn hạn. Bài viết có thể liên kết tới tài nguyên, dự án hoặc cơ hội liên quan nhưng không nên dùng lời kêu gọi quá mức. Khu vực tin tức phải giữ được sự cân bằng giữa thông tin chính thức, nội dung hướng dẫn và câu chuyện phản ánh những kinh nghiệm thực tế."}]' AND seo_json='{"title":"Tin tức & câu chuyện | Xanh Sky First","description":"Thông tin có bối cảnh, câu chuyện có sự tôn trọng. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Khu vực tin tức đăng tải những thông tin đã được biên tập và công bố. Mỗi bài nên giúp người đọc hiểu sự việc, thời điểm, bên liên quan và nguồn căn cứ khi có dữ kiện cần kiểm chứng."},{"type":"heading","text":"Đọc đúng trạng thái của thông tin"},{"type":"paragraph","text":"Thông báo mở đăng ký, kế hoạch dự kiến, bản tin giữa kỳ và bài tổng kết có mục đích khác nhau. Một mốc thời gian hoặc mục tiêu được nêu trong kế hoạch không nên được hiểu là kết quả đã hoàn thành."},{"type":"heading","text":"Hình ảnh và trích dẫn"},{"type":"paragraph","text":"Ảnh cần có nguồn và quyền sử dụng phù hợp; lời trích dẫn phải giữ đúng ý nghĩa và bối cảnh. Thông tin cá nhân không liên quan đến câu chuyện cần được lược bỏ."},{"type":"heading","text":"Gửi phản hồi về bài viết"},{"type":"paragraph","text":"Nếu phát hiện sai tên, ngày, con số hoặc liên kết, hãy gửi thông tin cụ thể qua kênh liên hệ. Nội dung đã xuất bản cần được sửa khi phát hiện sai sót có ảnh hưởng đến ý nghĩa."}]',seo_json='{"title":"Tin tức và câu chuyện | Xanh Sky First","description":"Theo dõi thông tin, bài viết và câu chuyện đã được biên tập; phân biệt thông báo, kế hoạch và kết quả đã xác minh."}',updated_at=datetime('now') WHERE slug='page-tin-tuc' AND title='Tin tức & câu chuyện' AND status='published' AND blocks_json='[{"type":"heading","text":"Thông tin có bối cảnh, câu chuyện có sự tôn trọng"},{"type":"paragraph","text":"Tin tức và câu chuyện là nơi Xanh Sky First chia sẻ những cập nhật đã được kiểm tra, kiến thức liên quan đến môi trường, bài học từ quá trình chuẩn bị hoặc triển khai, cùng những góc nhìn hữu ích từ cộng đồng. Mỗi bài cần giúp người đọc phân biệt đâu là thông tin, đâu là ý kiến và đâu là định hướng đang được xem xét. Tiêu đề cần chính xác, không phóng đại sự kiện hoặc tạo cảm giác có thành tích chưa được xác minh."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Với bài viết về hoạt động, nội dung nên nêu bối cảnh, mục tiêu, người tổ chức, thời gian và kết quả ở mức đã có căn cứ. Hình ảnh cần có nguồn hợp lệ và mô tả phù hợp; người xuất hiện trong ảnh phải được tôn trọng quyền riêng tư. Không dùng ảnh minh họa để khiến người đọc tưởng rằng Xanh đã tổ chức một hoạt động chưa diễn ra. Khi bài viết nói về dữ liệu, phải cho biết đơn vị, kỳ thống kê và cách hiểu chỉ số."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Câu chuyện cộng đồng cần được kể có sự đồng thuận, không tiết lộ thông tin riêng tư hoặc khai thác khó khăn của người khác chỉ để tạo cảm xúc. Trích dẫn cần đúng ngữ cảnh; nội dung biên tập không làm thay đổi ý nghĩa lời nói. Khi có thông tin sai hoặc cần cập nhật, bài viết phải có quy trình sửa đổi minh bạch để người đọc hiểu phần nào đã thay đổi và vì sao."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Xanh ưu tiên nội dung có thể giúp người đọc hiểu sâu hơn hoặc đưa ra lựa chọn tốt hơn, không chỉ nội dung có khả năng thu hút tương tác ngắn hạn. Bài viết có thể liên kết tới tài nguyên, dự án hoặc cơ hội liên quan nhưng không nên dùng lời kêu gọi quá mức. Khu vực tin tức phải giữ được sự cân bằng giữa thông tin chính thức, nội dung hướng dẫn và câu chuyện phản ánh những kinh nghiệm thực tế."}]' AND seo_json='{"title":"Tin tức & câu chuyện | Xanh Sky First","description":"Thông tin có bối cảnh, câu chuyện có sự tôn trọng. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='page-tra-cuu' AND title='Tra cứu hồ sơ' AND status='published' AND blocks_json='[{"type":"heading","text":"Theo dõi trạng thái bằng thông tin chính xác"},{"type":"paragraph","text":"Khu vực tra cứu giúp người đã gửi biểu mẫu xem trạng thái xử lý của hồ sơ khi hệ thống đã cấp mã tiếp nhận tương ứng. Mã hồ sơ nên được lưu lại sau khi gửi thành công; khi cần tra cứu, hãy nhập đúng toàn bộ mã, tránh nhầm ký tự hoặc khoảng trắng. Nếu hệ thống không tìm thấy hồ sơ, trước tiên hãy kiểm tra mã được cấp và thử lại trước khi gửi yêu cầu hỗ trợ."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Kết quả tra cứu chỉ nên hiển thị lượng thông tin cần thiết để người gửi nhận biết hồ sơ và trạng thái hiện tại. Dữ liệu cá nhân, câu trả lời biểu mẫu, tệp đính kèm và ghi chú nội bộ không được đưa ra công khai qua mã tra cứu đơn giản. Các trạng thái như đã tiếp nhận, đang xem xét, cần bổ sung, đã duyệt hoặc đã hoàn tất cần có ý nghĩa rõ ràng và được cập nhật bởi người có quyền."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Tra cứu hồ sơ tham gia Xanh khác với tra cứu giấy chứng nhận hoặc văn bản được cấp trên các cổng khác của hệ sinh thái Sky First. Website cần chỉ dẫn đúng nơi xử lý từng loại mã, tránh khiến người dùng nhầm lẫn giữa mã đăng ký và mã tài liệu. Nếu chuyển sang hệ thống khác, liên kết phải có nguồn chính thức và mở theo cách dễ hiểu."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Nếu gặp lỗi tra cứu kéo dài, người dùng có thể liên hệ qua kênh hỗ trợ được công bố, cung cấp mã hồ sơ và mô tả lỗi ở mức cần thiết. Không nên gửi mật khẩu, mã xác thực hoặc dữ liệu nhạy cảm qua phần bình luận công khai. Xanh hướng đến một quy trình tra cứu rõ ràng, bảo vệ quyền riêng tư và thể hiện trạng thái dựa trên dữ liệu thực trong hệ thống."}]' AND seo_json='{"title":"Tra cứu hồ sơ | Xanh Sky First","description":"Theo dõi trạng thái bằng thông tin chính xác. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Mã hồ sơ giúp xác định đúng lượt đăng ký mà không cần công khai nội dung chi tiết. Hãy nhập đúng mã được cấp sau khi gửi biểu mẫu và giữ mã lại cho đến khi quy trình kết thúc."},{"type":"heading","text":"Ý nghĩa của trạng thái"},{"type":"paragraph","text":"“Đã tiếp nhận” cho biết hệ thống ghi nhận hồ sơ; “đang xem xét” cho biết hồ sơ đang được xử lý; “cần bổ sung” nghĩa là người gửi cần xem hướng dẫn tiếp theo. “Đã duyệt” hoặc “đã hoàn tất” chỉ nên xuất hiện sau khi có quyết định tương ứng."},{"type":"heading","text":"Khi không tra cứu được"},{"type":"paragraph","text":"Kiểm tra lại mã, kể cả dấu gạch nối, rồi thử lại nếu hồ sơ vừa gửi. Nếu lỗi tiếp diễn, liên hệ bằng kênh chính thức và chỉ cung cấp thông tin cần để xác minh. Không gửi mật khẩu, mã xác thực hoặc toàn bộ tài liệu hồ sơ trong nội dung liên hệ."},{"type":"heading","text":"Tra cứu giấy chứng nhận"},{"type":"paragraph","text":"Tra cứu hồ sơ đăng ký Xanh và tra cứu giấy chứng nhận là hai mục đích khác nhau. Với giấy chứng nhận, hãy sử dụng cổng tra cứu chung Sky First Network được liên kết từ trang Tra cứu."}]',seo_json='{"title":"Tra cứu hồ sơ | Xanh Sky First","description":"Dùng mã tiếp nhận để kiểm tra trạng thái cơ bản của hồ sơ; không gửi mật khẩu hoặc tài liệu cá nhân qua kênh công khai."}',updated_at=datetime('now') WHERE slug='page-tra-cuu' AND title='Tra cứu hồ sơ' AND status='published' AND blocks_json='[{"type":"heading","text":"Theo dõi trạng thái bằng thông tin chính xác"},{"type":"paragraph","text":"Khu vực tra cứu giúp người đã gửi biểu mẫu xem trạng thái xử lý của hồ sơ khi hệ thống đã cấp mã tiếp nhận tương ứng. Mã hồ sơ nên được lưu lại sau khi gửi thành công; khi cần tra cứu, hãy nhập đúng toàn bộ mã, tránh nhầm ký tự hoặc khoảng trắng. Nếu hệ thống không tìm thấy hồ sơ, trước tiên hãy kiểm tra mã được cấp và thử lại trước khi gửi yêu cầu hỗ trợ."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Kết quả tra cứu chỉ nên hiển thị lượng thông tin cần thiết để người gửi nhận biết hồ sơ và trạng thái hiện tại. Dữ liệu cá nhân, câu trả lời biểu mẫu, tệp đính kèm và ghi chú nội bộ không được đưa ra công khai qua mã tra cứu đơn giản. Các trạng thái như đã tiếp nhận, đang xem xét, cần bổ sung, đã duyệt hoặc đã hoàn tất cần có ý nghĩa rõ ràng và được cập nhật bởi người có quyền."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Tra cứu hồ sơ tham gia Xanh khác với tra cứu giấy chứng nhận hoặc văn bản được cấp trên các cổng khác của hệ sinh thái Sky First. Website cần chỉ dẫn đúng nơi xử lý từng loại mã, tránh khiến người dùng nhầm lẫn giữa mã đăng ký và mã tài liệu. Nếu chuyển sang hệ thống khác, liên kết phải có nguồn chính thức và mở theo cách dễ hiểu."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Nếu gặp lỗi tra cứu kéo dài, người dùng có thể liên hệ qua kênh hỗ trợ được công bố, cung cấp mã hồ sơ và mô tả lỗi ở mức cần thiết. Không nên gửi mật khẩu, mã xác thực hoặc dữ liệu nhạy cảm qua phần bình luận công khai. Xanh hướng đến một quy trình tra cứu rõ ràng, bảo vệ quyền riêng tư và thể hiện trạng thái dựa trên dữ liệu thực trong hệ thống."}]' AND seo_json='{"title":"Tra cứu hồ sơ | Xanh Sky First","description":"Theo dõi trạng thái bằng thông tin chính xác. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='tai-nguyen-giao-duc' AND title='Giáo dục môi trường' AND status='published' AND blocks_json='[{"type":"heading","text":"Tài nguyên giáo dục cần giúp người học hiểu bối cảnh và thực hành được điều đã học."},{"type":"paragraph","text":"Một tài liệu giáo dục tốt có mục tiêu học tập rõ ràng, giải thích thuật ngữ, ví dụ dễ liên hệ và hoạt động thực hành phù hợp với lứa tuổi hoặc nhóm người đọc. Với chủ đề môi trường, người học cần hiểu cả lựa chọn cá nhân lẫn điều kiện hệ thống như hạ tầng thu gom, khả năng tiếp cận sản phẩm thay thế và bối cảnh địa phương. Tránh biến nội dung phức tạp thành thông điệp đơn giản nhưng gây hiểu nhầm."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Tài nguyên có thể gồm bài đọc, hướng dẫn thảo luận, bảng kiểm, mẫu quan sát, câu hỏi phản tư hoặc hoạt động nhóm. Nội dung cần chỉ rõ điều kiện sử dụng và nguồn tham khảo. Khi sử dụng hình ảnh hoặc tài liệu bên ngoài, cần tôn trọng quyền tác giả và ghi nhận nguồn. Tài liệu nên được rà soát định kỳ, nhất là những phần có dữ liệu hoặc khuyến nghị thay đổi theo thời gian."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Người sử dụng có thể gửi phản hồi về độ dễ hiểu, tính phù hợp và những điểm còn thiếu. Việc cải tiến nên dựa trên phản hồi cụ thể, không chỉ lượt xem. Xanh hướng đến tài nguyên giúp người học tự đặt câu hỏi, phân biệt bằng chứng với ý kiến và biết cách chuyển kiến thức thành lựa chọn an toàn, phù hợp với hoàn cảnh thật."}]' AND seo_json='{"title":"Giáo dục môi trường | Xanh Sky First","description":"Tài nguyên giáo dục cần giúp người học hiểu bối cảnh và thực hành được điều đã học. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Tài liệu giáo dục môi trường cần giúp người học hiểu một vấn đề và biết cách tìm hiểu thêm, không chỉ ghi nhớ khẩu hiệu. Mục tiêu học tập nên rõ; thuật ngữ cần được giải thích và ví dụ cần phù hợp với lứa tuổi, kinh nghiệm cùng bối cảnh địa phương."},{"type":"heading","text":"Gắn kiến thức với điều kiện thực tế"},{"type":"paragraph","text":"Một lựa chọn liên quan đến môi trường thường chịu ảnh hưởng của chi phí, hạ tầng, khả năng tiếp cận sản phẩm thay thế và dịch vụ tại nơi sống. Khi thảo luận giải pháp, nên phân biệt điều cá nhân có thể làm với điều cần sự phối hợp của cộng đồng hoặc hệ thống."},{"type":"heading","text":"Kiểm tra nguồn và quyền sử dụng"},{"type":"paragraph","text":"Tài liệu nên ghi rõ nguồn tham khảo, thời điểm cập nhật và điều kiện áp dụng. Với ảnh hoặc nội dung của đơn vị khác, hãy kiểm tra giấy phép và ghi nguồn. Những khuyến nghị có thể thay đổi theo thời gian cần được rà soát định kỳ."},{"type":"heading","text":"Cải thiện từ phản hồi"},{"type":"paragraph","text":"Phản hồi cụ thể về phần khó hiểu, thiếu ví dụ hoặc không phù hợp sẽ giúp tài liệu hữu ích hơn. Lượt xem không phải thước đo duy nhất; điều quan trọng là người học có hiểu đúng và sử dụng thông tin phù hợp hay không."}]',seo_json='{"title":"Giáo dục môi trường | Tài nguyên Xanh Sky First","description":"Gợi ý lựa chọn tài liệu giáo dục môi trường có mục tiêu học tập, nguồn tham khảo và hoạt động phù hợp với người học."}',updated_at=datetime('now') WHERE slug='tai-nguyen-giao-duc' AND title='Giáo dục môi trường' AND status='published' AND blocks_json='[{"type":"heading","text":"Tài nguyên giáo dục cần giúp người học hiểu bối cảnh và thực hành được điều đã học."},{"type":"paragraph","text":"Một tài liệu giáo dục tốt có mục tiêu học tập rõ ràng, giải thích thuật ngữ, ví dụ dễ liên hệ và hoạt động thực hành phù hợp với lứa tuổi hoặc nhóm người đọc. Với chủ đề môi trường, người học cần hiểu cả lựa chọn cá nhân lẫn điều kiện hệ thống như hạ tầng thu gom, khả năng tiếp cận sản phẩm thay thế và bối cảnh địa phương. Tránh biến nội dung phức tạp thành thông điệp đơn giản nhưng gây hiểu nhầm."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Tài nguyên có thể gồm bài đọc, hướng dẫn thảo luận, bảng kiểm, mẫu quan sát, câu hỏi phản tư hoặc hoạt động nhóm. Nội dung cần chỉ rõ điều kiện sử dụng và nguồn tham khảo. Khi sử dụng hình ảnh hoặc tài liệu bên ngoài, cần tôn trọng quyền tác giả và ghi nhận nguồn. Tài liệu nên được rà soát định kỳ, nhất là những phần có dữ liệu hoặc khuyến nghị thay đổi theo thời gian."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Người sử dụng có thể gửi phản hồi về độ dễ hiểu, tính phù hợp và những điểm còn thiếu. Việc cải tiến nên dựa trên phản hồi cụ thể, không chỉ lượt xem. Xanh hướng đến tài nguyên giúp người học tự đặt câu hỏi, phân biệt bằng chứng với ý kiến và biết cách chuyển kiến thức thành lựa chọn an toàn, phù hợp với hoàn cảnh thật."}]' AND seo_json='{"title":"Giáo dục môi trường | Xanh Sky First","description":"Tài nguyên giáo dục cần giúp người học hiểu bối cảnh và thực hành được điều đã học. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='tai-nguyen-song-xanh' AND title='Lối sống và tiêu dùng bền vững' AND status='published' AND blocks_json='[{"type":"heading","text":"Thay đổi thói quen bền vững bắt đầu bằng lựa chọn khả thi, không phải cảm giác hoàn hảo."},{"type":"paragraph","text":"Lối sống bền vững có thể liên quan đến việc sử dụng đồ dùng lâu hơn, giảm lãng phí, lựa chọn phương tiện phù hợp, sử dụng tài nguyên tiết kiệm và tìm hiểu cách xử lý chất thải tại địa phương. Không phải lựa chọn nào cũng phù hợp với mọi người; chi phí, điều kiện sống, khả năng tiếp cận dịch vụ và thời gian đều ảnh hưởng đến cách áp dụng. Nội dung hướng dẫn nên giúp người đọc cân nhắc chứ không phán xét."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Một lời khuyên cần giải thích điều kiện và giới hạn. Ví dụ, tái sử dụng chỉ hữu ích khi món đồ phù hợp với mục đích, được vệ sinh đúng cách và không tạo ra rủi ro mới. Phân loại rác cần gắn với khả năng thu gom và xử lý thực tế, bởi việc phân loại ở nhà không bảo đảm kết quả nếu hệ thống tiếp nhận chưa đáp ứng. Những khác biệt này nên được trình bày rõ để tránh kỳ vọng sai."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Xanh khuyến khích bắt đầu từ một thay đổi nhỏ có thể duy trì, theo dõi điều gì thuận lợi và điều gì gây khó khăn, sau đó điều chỉnh. Người đọc có thể chia sẻ kinh nghiệm như một tình huống tham khảo thay vì công thức bắt buộc. Cách tiếp cận thực tế giúp giảm cảm giác tội lỗi và tạo điều kiện để thói quen tốt có thể được duy trì lâu hơn."}]' AND seo_json='{"title":"Lối sống và tiêu dùng bền vững | Xanh Sky First","description":"Thay đổi thói quen bền vững bắt đầu bằng lựa chọn khả thi, không phải cảm giác hoàn hảo. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Không có một cách sống bền vững giống nhau cho tất cả mọi người. Chi phí, nơi ở, thời gian, sức khỏe và dịch vụ tại địa phương đều ảnh hưởng đến lựa chọn khả thi. Hãy bắt đầu bằng điều có thể duy trì thay vì cố theo một danh sách hoàn hảo."},{"type":"heading","text":"Xem xét cả vòng đời của lựa chọn"},{"type":"paragraph","text":"Dùng đồ lâu hơn, sửa chữa khi phù hợp, giảm lãng phí và sử dụng tài nguyên tiết kiệm có thể là những điểm bắt đầu. Tuy vậy, tái sử dụng cần bảo đảm vệ sinh và an toàn; phân loại rác ở nhà chỉ có ý nghĩa khi phù hợp với cách thu gom, xử lý tại nơi bạn sống."},{"type":"heading","text":"Đừng biến lời khuyên thành áp lực"},{"type":"paragraph","text":"Một phương án có chi phí cao hoặc khó tiếp cận không phù hợp với mọi gia đình. Nội dung hướng dẫn nên nêu điều kiện và giới hạn, để người đọc cân nhắc chứ không bị đánh giá vì chưa thể làm theo."},{"type":"heading","text":"Thử, theo dõi và điều chỉnh"},{"type":"paragraph","text":"Chọn một thay đổi nhỏ, quan sát điều gì thuận lợi và điều gì gây khó khăn, sau đó điều chỉnh. Nếu chia sẻ kinh nghiệm, hãy mô tả hoàn cảnh cụ thể để người khác hiểu đó là gợi ý tham khảo chứ không phải công thức bắt buộc."}]',seo_json='{"title":"Lối sống và tiêu dùng bền vững | Xanh Sky First","description":"Gợi ý lựa chọn sống bền vững theo điều kiện thực tế, cân nhắc chi phí, hạ tầng, khả năng sử dụng và xử lý sau cùng."}',updated_at=datetime('now') WHERE slug='tai-nguyen-song-xanh' AND title='Lối sống và tiêu dùng bền vững' AND status='published' AND blocks_json='[{"type":"heading","text":"Thay đổi thói quen bền vững bắt đầu bằng lựa chọn khả thi, không phải cảm giác hoàn hảo."},{"type":"paragraph","text":"Lối sống bền vững có thể liên quan đến việc sử dụng đồ dùng lâu hơn, giảm lãng phí, lựa chọn phương tiện phù hợp, sử dụng tài nguyên tiết kiệm và tìm hiểu cách xử lý chất thải tại địa phương. Không phải lựa chọn nào cũng phù hợp với mọi người; chi phí, điều kiện sống, khả năng tiếp cận dịch vụ và thời gian đều ảnh hưởng đến cách áp dụng. Nội dung hướng dẫn nên giúp người đọc cân nhắc chứ không phán xét."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Một lời khuyên cần giải thích điều kiện và giới hạn. Ví dụ, tái sử dụng chỉ hữu ích khi món đồ phù hợp với mục đích, được vệ sinh đúng cách và không tạo ra rủi ro mới. Phân loại rác cần gắn với khả năng thu gom và xử lý thực tế, bởi việc phân loại ở nhà không bảo đảm kết quả nếu hệ thống tiếp nhận chưa đáp ứng. Những khác biệt này nên được trình bày rõ để tránh kỳ vọng sai."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Xanh khuyến khích bắt đầu từ một thay đổi nhỏ có thể duy trì, theo dõi điều gì thuận lợi và điều gì gây khó khăn, sau đó điều chỉnh. Người đọc có thể chia sẻ kinh nghiệm như một tình huống tham khảo thay vì công thức bắt buộc. Cách tiếp cận thực tế giúp giảm cảm giác tội lỗi và tạo điều kiện để thói quen tốt có thể được duy trì lâu hơn."}]' AND seo_json='{"title":"Lối sống và tiêu dùng bền vững | Xanh Sky First","description":"Thay đổi thói quen bền vững bắt đầu bằng lựa chọn khả thi, không phải cảm giác hoàn hảo. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='tham-gia-cau-hoi' AND title='Câu hỏi thường gặp khi tham gia' AND status='published' AND blocks_json='[{"type":"heading","text":"Những câu trả lời rõ ràng giúp người mới quyết định có nên đăng ký và chuẩn bị như thế nào."},{"type":"paragraph","text":"Bạn có cần kinh nghiệm trước không? Điều này phụ thuộc vào từng cơ hội. Các hoạt động giới thiệu kiến thức hoặc nhiệm vụ cơ bản có thể mở cho người mới, trong khi một số phần việc cần chuyên môn hoặc đào tạo phù hợp. Trang đăng ký phải nêu yêu cầu cụ thể; không nên khẳng định mọi hoạt động đều phù hợp với tất cả mọi người."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Tham gia có mất phí hay cần tự chuẩn bị vật dụng không? Chỉ nên công bố câu trả lời khi chương trình đã xác nhận rõ điều kiện. Nếu có chi phí phát sinh, đơn vị tổ chức phải thông báo trước, không để người tham gia bất ngờ. Nếu chương trình thay đổi hoặc bị hoãn, thông tin liên hệ và phương án thông báo cần được nêu để người đăng ký biết cách xử lý."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Sau khi gửi form, bạn nên lưu mã tiếp nhận và theo dõi trạng thái qua đường dẫn tra cứu khi chức năng đó được hỗ trợ. Gửi hồ sơ không đồng nghĩa được chọn ngay; người phụ trách có thể cần thời gian xem xét hoặc đề nghị bổ sung. Nếu có câu hỏi chưa được trả lời, hãy dùng kênh liên hệ chính thức và chỉ gửi thông tin cá nhân cần thiết để giải quyết vấn đề."}]' AND seo_json='{"title":"Câu hỏi thường gặp khi tham gia | Xanh Sky First","description":"Những câu trả lời rõ ràng giúp người mới quyết định có nên đăng ký và chuẩn bị như thế nào. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"heading","text":"Tôi có cần kinh nghiệm trước không?"},{"type":"paragraph","text":"Tùy từng cơ hội. Một số nhiệm vụ có thể phù hợp với người mới; những phần việc khác cần kỹ năng, đào tạo hoặc kinh nghiệm cụ thể. Hãy xem yêu cầu được nêu trong trang của chính chương trình."},{"type":"heading","text":"Có mất phí hoặc cần tự chuẩn bị vật dụng không?"},{"type":"paragraph","text":"Chỉ dựa vào thông tin đã xác nhận của chương trình. Nếu phát sinh chi phí hoặc cần vật dụng riêng, điều đó cần được thông báo trước khi bạn quyết định đăng ký. Không suy luận quyền lợi từ một hoạt động khác."},{"type":"heading","text":"Gửi hồ sơ có nghĩa là đã được chọn?"},{"type":"paragraph","text":"Không. Gửi hồ sơ chỉ là bước đề nghị được xem xét. Người phụ trách có thể cần thời gian đọc hồ sơ hoặc yêu cầu bổ sung; hãy lưu mã tiếp nhận nếu hệ thống cấp mã và theo dõi trạng thái theo hướng dẫn."},{"type":"heading","text":"Tôi cần hỏi thêm hoặc gặp lỗi thì làm sao?"},{"type":"paragraph","text":"Dùng trang Liên hệ, nêu tên chương trình hoặc biểu mẫu và mô tả vấn đề. Chỉ cung cấp thông tin cần thiết để giải quyết yêu cầu; không gửi mật khẩu hoặc mã xác thực."}]',seo_json='{"title":"Câu hỏi thường gặp khi tham gia | Xanh Sky First","description":"Giải đáp những điều cần kiểm tra trước khi đăng ký: kinh nghiệm, chi phí, điều kiện, xác nhận hồ sơ và cách liên hệ."}',updated_at=datetime('now') WHERE slug='tham-gia-cau-hoi' AND title='Câu hỏi thường gặp khi tham gia' AND status='published' AND blocks_json='[{"type":"heading","text":"Những câu trả lời rõ ràng giúp người mới quyết định có nên đăng ký và chuẩn bị như thế nào."},{"type":"paragraph","text":"Bạn có cần kinh nghiệm trước không? Điều này phụ thuộc vào từng cơ hội. Các hoạt động giới thiệu kiến thức hoặc nhiệm vụ cơ bản có thể mở cho người mới, trong khi một số phần việc cần chuyên môn hoặc đào tạo phù hợp. Trang đăng ký phải nêu yêu cầu cụ thể; không nên khẳng định mọi hoạt động đều phù hợp với tất cả mọi người."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Tham gia có mất phí hay cần tự chuẩn bị vật dụng không? Chỉ nên công bố câu trả lời khi chương trình đã xác nhận rõ điều kiện. Nếu có chi phí phát sinh, đơn vị tổ chức phải thông báo trước, không để người tham gia bất ngờ. Nếu chương trình thay đổi hoặc bị hoãn, thông tin liên hệ và phương án thông báo cần được nêu để người đăng ký biết cách xử lý."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Sau khi gửi form, bạn nên lưu mã tiếp nhận và theo dõi trạng thái qua đường dẫn tra cứu khi chức năng đó được hỗ trợ. Gửi hồ sơ không đồng nghĩa được chọn ngay; người phụ trách có thể cần thời gian xem xét hoặc đề nghị bổ sung. Nếu có câu hỏi chưa được trả lời, hãy dùng kênh liên hệ chính thức và chỉ gửi thông tin cá nhân cần thiết để giải quyết vấn đề."}]' AND seo_json='{"title":"Câu hỏi thường gặp khi tham gia | Xanh Sky First","description":"Những câu trả lời rõ ràng giúp người mới quyết định có nên đăng ký và chuẩn bị như thế nào. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='tham-gia-quy-trinh' AND title='Quy trình đăng ký và tiếp nhận' AND status='published' AND blocks_json='[{"type":"heading","text":"Biểu mẫu cần dễ hiểu, chỉ thu thập dữ liệu cần thiết và thông báo rõ kết quả gửi."},{"type":"paragraph","text":"Trước khi điền, hãy đọc tên biểu mẫu, mục đích tiếp nhận, điều kiện tham gia và thời hạn nếu có. Các trường bắt buộc phải được đánh dấu rõ, còn trường không bắt buộc cần được nhận biết dễ dàng. Nếu cần tải tài liệu, biểu mẫu nên giải thích loại tệp và mục đích sử dụng. Người dùng không nên phải cung cấp thông tin vượt quá yêu cầu thực tế của chương trình."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Khi gửi, hệ thống cần kiểm tra dữ liệu ở cả trình duyệt và máy chủ, hiển thị lỗi gần trường liên quan, chống gửi lặp và chỉ thông báo thành công sau khi dữ liệu đã được lưu. Khi có mã hồ sơ, mã cần dễ sao chép và lưu lại. Email xác nhận chỉ được gửi nếu dịch vụ được cấu hình; trường hợp gửi email lỗi không nên làm mất hồ sơ đã lưu thành công."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Thông tin đăng ký phải được giới hạn cho người có quyền xử lý và chỉ sử dụng theo mục đích đã thông báo. Người phụ trách nên cập nhật trạng thái theo quy trình thống nhất. Nếu cần bổ sung thông tin, hãy giải thích rõ phần cần bổ sung và kênh gửi an toàn. Cách tiếp nhận nhất quán giúp người đăng ký hiểu điều gì xảy ra sau khi gửi, đồng thời giảm khối lượng liên hệ lặp lại."}]' AND seo_json='{"title":"Quy trình đăng ký và tiếp nhận | Xanh Sky First","description":"Biểu mẫu cần dễ hiểu, chỉ thu thập dữ liệu cần thiết và thông báo rõ kết quả gửi. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"heading","text":"1. Đọc điều kiện trước khi điền"},{"type":"paragraph","text":"Xác định mục đích của biểu mẫu, đối tượng phù hợp, thời hạn và những tài liệu cần chuẩn bị. Trường bắt buộc và trường không bắt buộc cần được phân biệt rõ."},{"type":"heading","text":"2. Chỉ cung cấp thông tin cần thiết"},{"type":"paragraph","text":"Điền thông tin chính xác và kiểm tra lại trước khi gửi. Nếu phải tải tệp, đọc yêu cầu về loại tệp, dung lượng và mục đích sử dụng. Không đính kèm giấy tờ riêng tư nếu biểu mẫu không yêu cầu."},{"type":"heading","text":"3. Lưu thông tin tiếp nhận"},{"type":"paragraph","text":"Sau khi gửi, chờ xác nhận từ hệ thống. Nếu có mã hồ sơ, hãy lưu lại để tra cứu. Nếu không thấy xác nhận hoặc gặp lỗi, kiểm tra trạng thái trước khi gửi lại để tránh tạo bản ghi trùng."},{"type":"heading","text":"4. Theo dõi bước tiếp theo"},{"type":"paragraph","text":"Hồ sơ có thể được tiếp nhận, xem xét hoặc yêu cầu bổ sung tùy quy trình. Khi cần cung cấp thêm thông tin, hãy dùng kênh phù hợp và kiểm tra người nhận trước khi gửi tài liệu."}]',seo_json='{"title":"Quy trình đăng ký và tiếp nhận | Xanh Sky First","description":"Các bước đăng ký rõ ràng: đọc yêu cầu, điền thông tin cần thiết, lưu mã tiếp nhận và theo dõi trạng thái hồ sơ."}',updated_at=datetime('now') WHERE slug='tham-gia-quy-trinh' AND title='Quy trình đăng ký và tiếp nhận' AND status='published' AND blocks_json='[{"type":"heading","text":"Biểu mẫu cần dễ hiểu, chỉ thu thập dữ liệu cần thiết và thông báo rõ kết quả gửi."},{"type":"paragraph","text":"Trước khi điền, hãy đọc tên biểu mẫu, mục đích tiếp nhận, điều kiện tham gia và thời hạn nếu có. Các trường bắt buộc phải được đánh dấu rõ, còn trường không bắt buộc cần được nhận biết dễ dàng. Nếu cần tải tài liệu, biểu mẫu nên giải thích loại tệp và mục đích sử dụng. Người dùng không nên phải cung cấp thông tin vượt quá yêu cầu thực tế của chương trình."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Khi gửi, hệ thống cần kiểm tra dữ liệu ở cả trình duyệt và máy chủ, hiển thị lỗi gần trường liên quan, chống gửi lặp và chỉ thông báo thành công sau khi dữ liệu đã được lưu. Khi có mã hồ sơ, mã cần dễ sao chép và lưu lại. Email xác nhận chỉ được gửi nếu dịch vụ được cấu hình; trường hợp gửi email lỗi không nên làm mất hồ sơ đã lưu thành công."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Thông tin đăng ký phải được giới hạn cho người có quyền xử lý và chỉ sử dụng theo mục đích đã thông báo. Người phụ trách nên cập nhật trạng thái theo quy trình thống nhất. Nếu cần bổ sung thông tin, hãy giải thích rõ phần cần bổ sung và kênh gửi an toàn. Cách tiếp nhận nhất quán giúp người đăng ký hiểu điều gì xảy ra sau khi gửi, đồng thời giảm khối lượng liên hệ lặp lại."}]' AND seo_json='{"title":"Quy trình đăng ký và tiếp nhận | Xanh Sky First","description":"Biểu mẫu cần dễ hiểu, chỉ thu thập dữ liệu cần thiết và thông báo rõ kết quả gửi. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='tin-tuc-quy-chuan' AND title='Tiêu chuẩn biên tập và xác minh' AND status='published' AND blocks_json='[{"type":"heading","text":"Mỗi nội dung công khai cần được biên tập để rõ ràng, có nguồn và không gây hiểu nhầm."},{"type":"paragraph","text":"Trước khi xuất bản, người phụ trách cần kiểm tra tên riêng, ngày tháng, con số, địa điểm, nguồn ảnh và quyền sử dụng nội dung. Bài viết phải phân biệt thông tin đã xác nhận với kế hoạch đang dự kiến. Nếu thiếu dữ kiện quan trọng, nên chờ xác minh hoặc nêu rõ phần chưa chắc chắn thay vì lấp khoảng trống bằng suy đoán."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Nội dung có số liệu nên ghi nguồn, đơn vị, kỳ thống kê và phương pháp hiểu chỉ số. Ví dụ, lượt tham gia không giống số người duy nhất; khối lượng rác thu gom cần có cách ghi nhận và đơn vị phù hợp. Khi dùng lời kể hoặc trích dẫn, phải bảo đảm không làm thay đổi ý nghĩa và tôn trọng sự đồng ý của người liên quan."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Sau khi xuất bản, nếu phát hiện sai sót, nội dung nên được sửa kịp thời và có ghi nhận khi thay đổi ảnh hưởng đáng kể đến ý nghĩa. Người đọc cần có kênh gửi phản hồi. Quy trình này giúp website duy trì độ tin cậy và khuyến khích một văn hóa truyền thông coi trọng tính chính xác hơn là tốc độ hoặc sự chú ý tức thời."}]' AND seo_json='{"title":"Tiêu chuẩn biên tập và xác minh | Xanh Sky First","description":"Mỗi nội dung công khai cần được biên tập để rõ ràng, có nguồn và không gây hiểu nhầm. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Trước khi xuất bản, người biên tập cần kiểm tra tên riêng, ngày tháng, địa điểm, con số, nguồn ảnh và quyền sử dụng nội dung. Nếu dữ kiện quan trọng chưa có căn cứ, hãy chờ xác minh hoặc ghi rõ phần chưa chắc chắn."},{"type":"heading","text":"Số liệu phải có ngữ cảnh"},{"type":"paragraph","text":"Khi công bố số liệu, cần nêu nguồn, đơn vị, thời điểm và cách ghi nhận. Lượt tham gia không nhất thiết là số người riêng biệt; khối lượng rác thu gom cần có đơn vị và cách cân đếm phù hợp. Không dùng một chỉ số thay cho toàn bộ tác động của chương trình."},{"type":"heading","text":"Tôn trọng người và tài liệu được trích dẫn"},{"type":"paragraph","text":"Lời kể và trích dẫn phải giữ đúng nghĩa, không cắt ghép làm thay đổi quan điểm. Ảnh và tài liệu cần có quyền sử dụng phù hợp; thông tin riêng tư nên được lược bỏ khi không cần cho nội dung."},{"type":"heading","text":"Sửa sai sau khi đăng"},{"type":"paragraph","text":"Nếu phát hiện lỗi ảnh hưởng đến ý nghĩa, hãy sửa kịp thời và ghi nhận thay đổi khi cần. Phản hồi từ độc giả nên được xem như một đầu mối kiểm tra, không mặc định là đúng hoặc sai khi chưa đối chiếu."}]',seo_json='{"title":"Tiêu chuẩn biên tập và xác minh | Xanh Sky First","description":"Nguyên tắc kiểm tra tên, ngày tháng, số liệu, hình ảnh, quyền sử dụng và cập nhật sai sót trước và sau khi xuất bản."}',updated_at=datetime('now') WHERE slug='tin-tuc-quy-chuan' AND title='Tiêu chuẩn biên tập và xác minh' AND status='published' AND blocks_json='[{"type":"heading","text":"Mỗi nội dung công khai cần được biên tập để rõ ràng, có nguồn và không gây hiểu nhầm."},{"type":"paragraph","text":"Trước khi xuất bản, người phụ trách cần kiểm tra tên riêng, ngày tháng, con số, địa điểm, nguồn ảnh và quyền sử dụng nội dung. Bài viết phải phân biệt thông tin đã xác nhận với kế hoạch đang dự kiến. Nếu thiếu dữ kiện quan trọng, nên chờ xác minh hoặc nêu rõ phần chưa chắc chắn thay vì lấp khoảng trống bằng suy đoán."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Nội dung có số liệu nên ghi nguồn, đơn vị, kỳ thống kê và phương pháp hiểu chỉ số. Ví dụ, lượt tham gia không giống số người duy nhất; khối lượng rác thu gom cần có cách ghi nhận và đơn vị phù hợp. Khi dùng lời kể hoặc trích dẫn, phải bảo đảm không làm thay đổi ý nghĩa và tôn trọng sự đồng ý của người liên quan."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Sau khi xuất bản, nếu phát hiện sai sót, nội dung nên được sửa kịp thời và có ghi nhận khi thay đổi ảnh hưởng đáng kể đến ý nghĩa. Người đọc cần có kênh gửi phản hồi. Quy trình này giúp website duy trì độ tin cậy và khuyến khích một văn hóa truyền thông coi trọng tính chính xác hơn là tốc độ hoặc sự chú ý tức thời."}]' AND seo_json='{"title":"Tiêu chuẩn biên tập và xác minh | Xanh Sky First","description":"Mỗi nội dung công khai cần được biên tập để rõ ràng, có nguồn và không gây hiểu nhầm. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='tra-cuu-ma-ho-so' AND title='Mã hồ sơ và trạng thái xử lý' AND status='published' AND blocks_json='[{"type":"heading","text":"Mã hồ sơ giúp hệ thống tìm đúng lượt đăng ký mà không cần công khai toàn bộ thông tin cá nhân."},{"type":"paragraph","text":"Sau khi biểu mẫu được lưu thành công, hệ thống có thể cấp một mã hồ sơ riêng. Hãy sao chép chính xác mã này và giữ lại cho đến khi quy trình kết thúc. Không đăng mã công khai trên mạng xã hội nếu không cần thiết. Nếu mã được gửi qua email, hãy kiểm tra cả thư mục thư rác và địa chỉ email đã khai báo trong biểu mẫu."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Các trạng thái cần thể hiện tiến trình xử lý chứ không phải lời hứa về kết quả. “Đã tiếp nhận” cho biết hồ sơ đã được ghi nhận; “đang xem xét” nghĩa là người phụ trách đang xử lý; “cần bổ sung” chỉ ra người gửi cần thực hiện bước tiếp theo; “đã duyệt” hoặc “đã hoàn tất” chỉ xuất hiện khi đã có quyết định tương ứng. Website nên giải thích trạng thái bằng ngôn ngữ dễ hiểu."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Nếu không tra cứu được, hãy kiểm tra lại mã và thử sau một khoảng thời gian ngắn nếu hồ sơ vừa gửi. Nếu lỗi tiếp diễn, liên hệ hỗ trợ bằng kênh chính thức và cung cấp mã cần thiết, không gửi mật khẩu hoặc mã xác thực. Hệ thống chỉ nên trả về thông tin tối thiểu để xác nhận hồ sơ, còn câu trả lời chi tiết và tệp đính kèm phải được bảo vệ."}]' AND seo_json='{"title":"Mã hồ sơ và trạng thái xử lý | Xanh Sky First","description":"Mã hồ sơ giúp hệ thống tìm đúng lượt đăng ký mà không cần công khai toàn bộ thông tin cá nhân. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
UPDATE pages SET blocks_json='[{"type":"paragraph","text":"Mã hồ sơ giúp hệ thống xác định một lượt đăng ký mà không cần công khai câu trả lời hay tài liệu cá nhân. Sau khi gửi thành công, hãy sao chép mã chính xác và giữ lại đến khi quy trình kết thúc."},{"type":"heading","text":"Hiểu từng trạng thái"},{"type":"paragraph","text":"“Đã tiếp nhận” nghĩa là hệ thống đã ghi nhận hồ sơ; “đang xem xét” cho biết hồ sơ đang được xử lý; “cần bổ sung thông tin” nghĩa là bạn cần xem hướng dẫn tiếp theo. “Đã duyệt”, “không phù hợp” hoặc “đã hoàn tất” chỉ phản ánh quyết định được ghi nhận trong hồ sơ."},{"type":"heading","text":"Bảo vệ mã và thông tin cá nhân"},{"type":"paragraph","text":"Không đăng mã hồ sơ ở nơi công khai khi không cần thiết. Khi liên hệ hỗ trợ, chỉ cung cấp mã và thông tin cần cho việc xác minh; không gửi mật khẩu, mã OTP hoặc tài liệu không liên quan."},{"type":"heading","text":"Nếu tra cứu chưa ra kết quả"},{"type":"paragraph","text":"Kiểm tra lại ký tự và dấu gạch nối, rồi thử lại nếu hồ sơ vừa được gửi. Nếu vấn đề tiếp diễn, liên hệ qua kênh chính thức. Hệ thống tra cứu chỉ nên hiển thị trạng thái cơ bản; dữ liệu chi tiết cần tiếp tục được bảo vệ."}]',seo_json='{"title":"Mã hồ sơ và trạng thái xử lý | Xanh Sky First","description":"Cách lưu và sử dụng mã hồ sơ, hiểu các trạng thái xử lý và liên hệ hỗ trợ mà không chia sẻ dữ liệu nhạy cảm."}',updated_at=datetime('now') WHERE slug='tra-cuu-ma-ho-so' AND title='Mã hồ sơ và trạng thái xử lý' AND status='published' AND blocks_json='[{"type":"heading","text":"Mã hồ sơ giúp hệ thống tìm đúng lượt đăng ký mà không cần công khai toàn bộ thông tin cá nhân."},{"type":"paragraph","text":"Sau khi biểu mẫu được lưu thành công, hệ thống có thể cấp một mã hồ sơ riêng. Hãy sao chép chính xác mã này và giữ lại cho đến khi quy trình kết thúc. Không đăng mã công khai trên mạng xã hội nếu không cần thiết. Nếu mã được gửi qua email, hãy kiểm tra cả thư mục thư rác và địa chỉ email đã khai báo trong biểu mẫu."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Các trạng thái cần thể hiện tiến trình xử lý chứ không phải lời hứa về kết quả. “Đã tiếp nhận” cho biết hồ sơ đã được ghi nhận; “đang xem xét” nghĩa là người phụ trách đang xử lý; “cần bổ sung” chỉ ra người gửi cần thực hiện bước tiếp theo; “đã duyệt” hoặc “đã hoàn tất” chỉ xuất hiện khi đã có quyết định tương ứng. Website nên giải thích trạng thái bằng ngôn ngữ dễ hiểu."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Nếu không tra cứu được, hãy kiểm tra lại mã và thử sau một khoảng thời gian ngắn nếu hồ sơ vừa gửi. Nếu lỗi tiếp diễn, liên hệ hỗ trợ bằng kênh chính thức và cung cấp mã cần thiết, không gửi mật khẩu hoặc mã xác thực. Hệ thống chỉ nên trả về thông tin tối thiểu để xác nhận hồ sơ, còn câu trả lời chi tiết và tệp đính kèm phải được bảo vệ."}]' AND seo_json='{"title":"Mã hồ sơ và trạng thái xử lý | Xanh Sky First","description":"Mã hồ sơ giúp hệ thống tìm đúng lượt đăng ký mà không cần công khai toàn bộ thông tin cá nhân. — nội dung hướng dẫn và thông tin của Xanh Sky First."}';
INSERT INTO page_revisions(page_id,title,blocks_json,seo_json,created_by,created_at) SELECT id,title,blocks_json,seo_json,NULL,datetime('now') FROM pages WHERE slug='home' AND title='Trang chủ' AND status='published' AND blocks_json='[{"id": "hero", "type": "hero", "eyebrow": "XANH SKY FIRST · MÔI TRƯỜNG & PHÁT TRIỂN BỀN VỮNG", "title": "HÀNH ĐỘNG HÔM NAY. XANH NGÀY MAI.", "body": "Xanh Sky First hướng đến việc kết nối người trẻ, cộng đồng, tri thức và những nguồn lực phù hợp để biến sự quan tâm dành cho môi trường thành những hành động có thể bắt đầu từ thực tế. Chúng tôi tin rằng thay đổi bền vững không nhất thiết phải khởi đầu bằng những điều thật lớn, mà có thể bắt đầu từ cách mỗi người hiểu một vấn đề, thay đổi một lựa chọn, chia sẻ một kiến thức hữu ích hoặc cùng những người xung quanh thực hiện một hành động cụ thể. Thông qua hoạt động cộng đồng, giáo dục môi trường, sáng kiến của người trẻ và những dự án được phát triển từng bước, Xanh Sky First mong muốn tạo ra một không gian để bất kỳ ai quan tâm cũng có thể tìm thấy cách tham gia phù hợp với mình.", "primary_label": "Khám phá Xanh", "primary_href": "/gioi-thieu", "secondary_label": "Cùng hành động", "secondary_href": "/tham-gia", "media_id": null, "visible": true}, {"id": "about", "type": "rich", "kicker": "VỀ XANH SKY FIRST", "title": "Một không gian để sự quan tâm trở thành hành động", "body": "Xanh Sky First được phát triển như một không gian dành cho môi trường, cộng đồng và phát triển bền vững trong hệ sinh thái Sky First. Xanh không giới hạn hoạt động ở một chiến dịch hoặc một hình thức tình nguyện duy nhất, mà hướng đến việc xây dựng một hành trình từ nhận thức đến hành động: tìm hiểu vấn đề, tiếp cận kiến thức, tham gia hoạt động, đóng góp chuyên môn, đề xuất sáng kiến và cùng phát triển những giải pháp phù hợp với thực tế. Trong quá trình phát triển, Xanh ưu tiên chất lượng của từng hoạt động, tính minh bạch của thông tin và khả năng tạo ra giá trị có thể tiếp tục sau khi một chương trình kết thúc, thay vì chạy theo những con số lớn hoặc những hoạt động chỉ có giá trị truyền thông trong thời gian ngắn.", "media_id": null, "layout": "split", "visible": true}, {"id": "pillars", "type": "cards", "kicker": "ĐIỀU XANH THEO ĐUỔI", "title": "Bốn nguyên tắc cho hành động có chiều sâu", "items": [{"title": "Hiểu đúng", "body": "Xanh lựa chọn bắt đầu từ việc hiểu vấn đề thay vì vội vàng tạo ra một hoạt động chỉ để có hình ảnh. Nội dung, tài nguyên và chương trình được định hướng để người tham gia có thể tiếp cận thông tin rõ ràng, phân biệt giữa thói quen tốt, giải pháp có cơ sở và những thông điệp dễ tạo cảm giác tích cực nhưng thiếu hiệu quả thực tế. Việc hiểu đúng cũng giúp mỗi người nhìn thấy mối liên hệ giữa môi trường, sức khỏe, cộng đồng, tiêu dùng và phát triển bền vững; từ đó đưa ra lựa chọn phù hợp với điều kiện của bản thân thay vì áp dụng một công thức duy nhất cho tất cả mọi người."}, {"title": "Hành động thật", "body": "Một hoạt động chỉ có ý nghĩa khi người tham gia biết mình đang làm gì, vì sao làm và kết quả được ghi nhận ra sao. Xanh ưu tiên những hành động có thể triển khai trong bối cảnh thực tế, có mục tiêu cụ thể, có người chịu trách nhiệm và có bước tổng kết sau khi kết thúc. Điều này có thể là một buổi chia sẻ, một hoạt động cộng đồng, một tài nguyên giáo dục hay một sáng kiến nhỏ tại địa phương. Quy mô không phải tiêu chí duy nhất; tính phù hợp, khả năng duy trì và mức độ tạo ra thay đổi tích cực mới là những yếu tố được đặt lên trước."}, {"title": "Kết nối cộng đồng", "body": "Nhiều vấn đề môi trường không thể được giải quyết bởi một cá nhân đơn lẻ. Xanh hướng đến việc tạo ra những điểm kết nối giữa người trẻ có mong muốn đóng góp, người có chuyên môn, nhóm cộng đồng, đơn vị đồng hành và các nguồn lực phù hợp. Việc kết nối không nhằm tạo ra một mạng lưới chỉ để gia tăng số lượng thành viên, mà để giúp những người có cùng mối quan tâm tìm thấy nhau, chia sẻ kinh nghiệm và cùng thực hiện những việc cụ thể. Mỗi kết nối tốt cần rõ mục tiêu, rõ vai trò và tôn trọng năng lực cũng như giới hạn của từng bên tham gia."}, {"title": "Tạo giá trị bền vững", "body": "Xanh không xem một chương trình là hoàn thành chỉ vì sự kiện đã kết thúc hoặc bài truyền thông đã được đăng. Những gì được tạo ra sau hoạt động — kinh nghiệm, tài liệu, dữ liệu, câu chuyện, mối quan hệ và khả năng tiếp tục hành động — đều là một phần của giá trị. Vì vậy, hệ thống được thiết kế để mỗi dự án có thể lưu lại tiến độ, tài liệu, kết quả và báo cáo; đồng thời những nội dung hữu ích có thể quay trở lại phục vụ cộng đồng. Tư duy này giúp Xanh phát triển từng bước, tránh chạy theo nhịp độ hoạt động dày nhưng thiếu chiều sâu và thiếu khả năng học hỏi từ chính những việc đã làm."}], "visible": true}, {"id": "fields", "type": "feature_grid", "kicker": "LĨNH VỰC HÀNH ĐỘNG", "title": "Năm hướng để bắt đầu", "items": ["Môi trường & không gian sống", "Giáo dục môi trường", "Lối sống & tiêu dùng bền vững", "Đổi mới & sáng kiến xanh", "Cộng đồng & phát triển bền vững"], "visible": true}, {"id": "projects", "type": "dynamic", "source": "project", "kicker": "CHƯƠNG TRÌNH & DỰ ÁN", "title": "Những việc đang được xây dựng và triển khai", "visible": true}, {"id": "impact", "type": "impact", "kicker": "DẤU ẤN XANH", "title": "Mỗi con số đại diện cho một hành động đã thực sự diễn ra.", "visible": true}, {"id": "opportunities", "type": "dynamic", "source": "opportunity", "kicker": "CƠ HỘI", "title": "Tìm một cách phù hợp để cùng hành động", "visible": true}, {"id": "news", "type": "dynamic", "source": "article", "kicker": "TIN TỨC & CÂU CHUYỆN", "title": "Nội dung mới từ Xanh", "visible": true}, {"id": "newsletter", "type": "newsletter", "kicker": "NEWSLETTER", "title": "Một chút Xanh trong hộp thư của bạn.", "body": "Chọn những nội dung bạn thực sự muốn nhận. Xanh không tự động đưa email từ các biểu mẫu khác vào danh sách newsletter và luôn cung cấp cách hủy đăng ký rõ ràng.", "visible": true}, {"id": "join", "type": "cta", "kicker": "THAM GIA XANH", "title": "Không cần bắt đầu bằng điều lớn. Chỉ cần bắt đầu bằng một điều bạn có thể làm.", "body": "Bạn có thể tham gia một hoạt động, trở thành tình nguyện viên, gửi một sáng kiến, đóng góp chuyên môn hoặc kết nối với Xanh để cùng phát triển một chương trình phù hợp với cộng đồng.", "label": "Cùng hành động", "href": "/tham-gia", "visible": true}]' AND seo_json='{"title": "Xanh Sky First — Hành động hôm nay. Xanh ngày mai.", "description": "Không gian kết nối người trẻ, cộng đồng và hành động vì môi trường, phát triển bền vững."}';
UPDATE pages SET blocks_json='[{"id":"hero","type":"hero","eyebrow":"MÔI TRƯỜNG · CỘNG ĐỒNG · THÔNG TIN THỰC TIỄN","title":"Từ điều bạn quan tâm đến bước có thể làm","body":"Tìm hiểu các chủ đề môi trường, xem hoạt động đã công bố và đọc kỹ điều kiện trước khi đăng ký. Xanh Sky First cung cấp thông tin, cơ hội tham gia và tài nguyên để bạn lựa chọn theo thời gian, kỹ năng và điều kiện thực tế của mình.","primary_label":"Khám phá dự án","primary_href":"/gioi-thieu","secondary_label":"Xem cơ hội tham gia","secondary_href":"/tham-gia","media_id":null,"visible":true},{"id":"about","type":"rich","kicker":"VỀ XANH SKY FIRST","title":"Hiểu vấn đề trước khi chọn giải pháp","body":"Website tập hợp nội dung về môi trường, cộng đồng và phát triển bền vững trong hệ sinh thái Sky First. Bạn có thể đọc tài nguyên, theo dõi hoạt động đã công bố, tìm cơ hội tham gia hoặc gửi câu hỏi trước khi đăng ký. Thông tin về mục tiêu, tiến độ và kết quả cần được phân biệt rõ để người đọc biết điều gì đã diễn ra và điều gì còn ở giai đoạn dự kiến.","media_id":null,"layout":"split","visible":true},{"id":"pillars","type":"cards","kicker":"CÁCH TIẾP CẬN","title":"Bốn điểm để kiểm tra một hành động có phù hợp","items":[{"title":"Bắt đầu từ thông tin","body":"Tìm hiểu vấn đề, bối cảnh và nguồn căn cứ trước khi đề xuất giải pháp. Khi chưa đủ dữ liệu, hãy nêu điều còn cần xác minh thay vì kết luận sớm."},{"title":"Làm rõ phần việc","body":"Mỗi hoạt động cần mô tả mục tiêu, nhiệm vụ, người phụ trách và cách ghi nhận kết quả. Quy mô không thay thế cho chất lượng hay mức độ phù hợp."},{"title":"Kết nối đúng nhu cầu","body":"Sự phối hợp có ích khi các bên hiểu mục tiêu, vai trò, thời gian và giới hạn của nhau. Không mặc định rằng mọi người đều có cùng điều kiện tham gia."},{"title":"Ghi nhận trung thực","body":"Phân biệt kế hoạch, tiến độ và kết quả. Số liệu cần có nguồn cùng cách ghi nhận; câu chuyện và hình ảnh phải được dùng đúng ngữ cảnh."}],"visible":true},{"id":"fields","type":"feature_grid","kicker":"CÁC CHỦ ĐỀ","title":"Tìm hiểu theo điều bạn đang quan tâm","items":["Môi trường và không gian sống","Giáo dục môi trường","Lối sống và tiêu dùng bền vững","Đổi mới và sáng kiến xanh","Cộng đồng và phát triển bền vững"],"visible":true},{"id":"projects","type":"dynamic","source":"project","kicker":"DỰ ÁN VÀ SÁNG KIẾN","title":"Theo dõi mục tiêu, tiến độ và kết quả đã công bố","visible":true},{"id":"impact","type":"impact","kicker":"DỮ LIỆU TÁC ĐỘNG","title":"Chỉ hiển thị số liệu có nguồn và trạng thái xác minh.","visible":true},{"id":"opportunities","type":"dynamic","source":"opportunity","kicker":"CƠ HỘI THAM GIA","title":"Chọn cơ hội theo thời gian và yêu cầu cụ thể","visible":true},{"id":"news","type":"dynamic","source":"article","kicker":"TIN TỨC VÀ CÂU CHUYỆN","title":"Thông tin mới, có bối cảnh và nguồn rõ ràng","visible":true},{"id":"newsletter","type":"newsletter","kicker":"BẢN TIN","title":"Nhận thông tin theo chủ đề bạn chọn","body":"Chọn những nội dung bạn muốn nhận. Email từ biểu mẫu khác không tự động được đưa vào danh sách bản tin; bạn có thể hủy đăng ký bằng liên kết trong email.","visible":true},{"id":"join","type":"cta","kicker":"BẮT ĐẦU TỪ ĐIỀU CÓ THỂ","title":"Chọn một bước vừa với điều kiện của bạn.","body":"Đọc tài nguyên, xem lịch hoạt động, gửi một sáng kiến hoặc hỏi trước khi đăng ký. Mỗi cơ hội có phạm vi và yêu cầu riêng; hãy chọn sau khi đã đọc thông tin.","label":"Xem cách tham gia","href":"/tham-gia","visible":true}]',seo_json='{"title":"Xanh Sky First | Dự án, hoạt động, kiến thức và cơ hội tham gia","description":"Thông tin về dự án, hoạt động, sáng kiến và tài nguyên môi trường, cộng đồng. Tìm điều kiện tham gia và nội dung đã được công bố."}',updated_at=datetime('now') WHERE slug='home' AND title='Trang chủ' AND status='published' AND blocks_json='[{"id": "hero", "type": "hero", "eyebrow": "XANH SKY FIRST · MÔI TRƯỜNG & PHÁT TRIỂN BỀN VỮNG", "title": "HÀNH ĐỘNG HÔM NAY. XANH NGÀY MAI.", "body": "Xanh Sky First hướng đến việc kết nối người trẻ, cộng đồng, tri thức và những nguồn lực phù hợp để biến sự quan tâm dành cho môi trường thành những hành động có thể bắt đầu từ thực tế. Chúng tôi tin rằng thay đổi bền vững không nhất thiết phải khởi đầu bằng những điều thật lớn, mà có thể bắt đầu từ cách mỗi người hiểu một vấn đề, thay đổi một lựa chọn, chia sẻ một kiến thức hữu ích hoặc cùng những người xung quanh thực hiện một hành động cụ thể. Thông qua hoạt động cộng đồng, giáo dục môi trường, sáng kiến của người trẻ và những dự án được phát triển từng bước, Xanh Sky First mong muốn tạo ra một không gian để bất kỳ ai quan tâm cũng có thể tìm thấy cách tham gia phù hợp với mình.", "primary_label": "Khám phá Xanh", "primary_href": "/gioi-thieu", "secondary_label": "Cùng hành động", "secondary_href": "/tham-gia", "media_id": null, "visible": true}, {"id": "about", "type": "rich", "kicker": "VỀ XANH SKY FIRST", "title": "Một không gian để sự quan tâm trở thành hành động", "body": "Xanh Sky First được phát triển như một không gian dành cho môi trường, cộng đồng và phát triển bền vững trong hệ sinh thái Sky First. Xanh không giới hạn hoạt động ở một chiến dịch hoặc một hình thức tình nguyện duy nhất, mà hướng đến việc xây dựng một hành trình từ nhận thức đến hành động: tìm hiểu vấn đề, tiếp cận kiến thức, tham gia hoạt động, đóng góp chuyên môn, đề xuất sáng kiến và cùng phát triển những giải pháp phù hợp với thực tế. Trong quá trình phát triển, Xanh ưu tiên chất lượng của từng hoạt động, tính minh bạch của thông tin và khả năng tạo ra giá trị có thể tiếp tục sau khi một chương trình kết thúc, thay vì chạy theo những con số lớn hoặc những hoạt động chỉ có giá trị truyền thông trong thời gian ngắn.", "media_id": null, "layout": "split", "visible": true}, {"id": "pillars", "type": "cards", "kicker": "ĐIỀU XANH THEO ĐUỔI", "title": "Bốn nguyên tắc cho hành động có chiều sâu", "items": [{"title": "Hiểu đúng", "body": "Xanh lựa chọn bắt đầu từ việc hiểu vấn đề thay vì vội vàng tạo ra một hoạt động chỉ để có hình ảnh. Nội dung, tài nguyên và chương trình được định hướng để người tham gia có thể tiếp cận thông tin rõ ràng, phân biệt giữa thói quen tốt, giải pháp có cơ sở và những thông điệp dễ tạo cảm giác tích cực nhưng thiếu hiệu quả thực tế. Việc hiểu đúng cũng giúp mỗi người nhìn thấy mối liên hệ giữa môi trường, sức khỏe, cộng đồng, tiêu dùng và phát triển bền vững; từ đó đưa ra lựa chọn phù hợp với điều kiện của bản thân thay vì áp dụng một công thức duy nhất cho tất cả mọi người."}, {"title": "Hành động thật", "body": "Một hoạt động chỉ có ý nghĩa khi người tham gia biết mình đang làm gì, vì sao làm và kết quả được ghi nhận ra sao. Xanh ưu tiên những hành động có thể triển khai trong bối cảnh thực tế, có mục tiêu cụ thể, có người chịu trách nhiệm và có bước tổng kết sau khi kết thúc. Điều này có thể là một buổi chia sẻ, một hoạt động cộng đồng, một tài nguyên giáo dục hay một sáng kiến nhỏ tại địa phương. Quy mô không phải tiêu chí duy nhất; tính phù hợp, khả năng duy trì và mức độ tạo ra thay đổi tích cực mới là những yếu tố được đặt lên trước."}, {"title": "Kết nối cộng đồng", "body": "Nhiều vấn đề môi trường không thể được giải quyết bởi một cá nhân đơn lẻ. Xanh hướng đến việc tạo ra những điểm kết nối giữa người trẻ có mong muốn đóng góp, người có chuyên môn, nhóm cộng đồng, đơn vị đồng hành và các nguồn lực phù hợp. Việc kết nối không nhằm tạo ra một mạng lưới chỉ để gia tăng số lượng thành viên, mà để giúp những người có cùng mối quan tâm tìm thấy nhau, chia sẻ kinh nghiệm và cùng thực hiện những việc cụ thể. Mỗi kết nối tốt cần rõ mục tiêu, rõ vai trò và tôn trọng năng lực cũng như giới hạn của từng bên tham gia."}, {"title": "Tạo giá trị bền vững", "body": "Xanh không xem một chương trình là hoàn thành chỉ vì sự kiện đã kết thúc hoặc bài truyền thông đã được đăng. Những gì được tạo ra sau hoạt động — kinh nghiệm, tài liệu, dữ liệu, câu chuyện, mối quan hệ và khả năng tiếp tục hành động — đều là một phần của giá trị. Vì vậy, hệ thống được thiết kế để mỗi dự án có thể lưu lại tiến độ, tài liệu, kết quả và báo cáo; đồng thời những nội dung hữu ích có thể quay trở lại phục vụ cộng đồng. Tư duy này giúp Xanh phát triển từng bước, tránh chạy theo nhịp độ hoạt động dày nhưng thiếu chiều sâu và thiếu khả năng học hỏi từ chính những việc đã làm."}], "visible": true}, {"id": "fields", "type": "feature_grid", "kicker": "LĨNH VỰC HÀNH ĐỘNG", "title": "Năm hướng để bắt đầu", "items": ["Môi trường & không gian sống", "Giáo dục môi trường", "Lối sống & tiêu dùng bền vững", "Đổi mới & sáng kiến xanh", "Cộng đồng & phát triển bền vững"], "visible": true}, {"id": "projects", "type": "dynamic", "source": "project", "kicker": "CHƯƠNG TRÌNH & DỰ ÁN", "title": "Những việc đang được xây dựng và triển khai", "visible": true}, {"id": "impact", "type": "impact", "kicker": "DẤU ẤN XANH", "title": "Mỗi con số đại diện cho một hành động đã thực sự diễn ra.", "visible": true}, {"id": "opportunities", "type": "dynamic", "source": "opportunity", "kicker": "CƠ HỘI", "title": "Tìm một cách phù hợp để cùng hành động", "visible": true}, {"id": "news", "type": "dynamic", "source": "article", "kicker": "TIN TỨC & CÂU CHUYỆN", "title": "Nội dung mới từ Xanh", "visible": true}, {"id": "newsletter", "type": "newsletter", "kicker": "NEWSLETTER", "title": "Một chút Xanh trong hộp thư của bạn.", "body": "Chọn những nội dung bạn thực sự muốn nhận. Xanh không tự động đưa email từ các biểu mẫu khác vào danh sách newsletter và luôn cung cấp cách hủy đăng ký rõ ràng.", "visible": true}, {"id": "join", "type": "cta", "kicker": "THAM GIA XANH", "title": "Không cần bắt đầu bằng điều lớn. Chỉ cần bắt đầu bằng một điều bạn có thể làm.", "body": "Bạn có thể tham gia một hoạt động, trở thành tình nguyện viên, gửi một sáng kiến, đóng góp chuyên môn hoặc kết nối với Xanh để cùng phát triển một chương trình phù hợp với cộng đồng.", "label": "Cùng hành động", "href": "/tham-gia", "visible": true}]' AND seo_json='{"title": "Xanh Sky First — Hành động hôm nay. Xanh ngày mai.", "description": "Không gian kết nối người trẻ, cộng đồng và hành động vì môi trường, phát triển bền vững."}';
